window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II y oraciones con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si yo fuera tú, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realidad de Eva – los deseos de Eva. Completa: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Pero le gustaría ser más alta.","why":"*grösser sein*: la forma de deseo de *sein* es **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Pero le gustaría hablar bien español.","why":"Hay un infinitivo al final (*sprechen*), así que el deseo es **würde** + infinitivo.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Pero preferiría trabajar como guía turística.","why":"Infinitivo al final (*arbeiten*) → **würde** + infinitivo. *lieber* = más bien / preferiblemente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Pero le gustaría tener un apartamento grande.","why":"*eine Wohnung haben*: la forma de deseo de *haben* es **hätte**. No hace falta infinitivo.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"¿Qué piensan las personas?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Relaciona cada imagen con una expresión del recuadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si no tuviera que trabajar, ahora estaría sentado en el jardín.","why":"La imagen 1 lo muestra trabajando y luego soñando en una tumbona. Después de una oración con *wenn*, la oración principal empieza por el verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si tuviera coche, no tendría que ir en bici bajo la lluvia.","why":"Va en bici bajo la lluvia; con un coche se lo ahorraría. *müsste* es el Konjunktiv II de *müssen*. *Velo* es la palabra suiza para *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si el autobús no llegara con retraso, llegaría puntual a la oficina.","why":"Como el autobús va con retraso, ella llega tarde al trabajo. *wäre* es el Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Reescribe las frases de a: empieza con la oración principal y luego la oración con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"No tendría que ir en bici bajo la lluvia si tuviera coche.","why":"Primero la oración principal y luego la oración con *wenn*. En la oración con *wenn* el verbo (*hätte*) va al final.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Llegaría puntual a la oficina si el autobús no llegara con retraso.","why":"El mismo esquema: oración principal, coma, *wenn* … verbo al final (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con las palabras del recuadro. Cada palabra se usa una vez; las tachadas se usan en el ejemplo.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Haría algunas cosas de otra manera si yo fuera la jefa de nuestra empresa.","why":"*machen* al final → **würde** + infinitivo. *Chefin sein* → **wäre**, al final de la oración con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si yo fuera Marco, haría sin falta una formación profesional.","why":"*Marco sein* → **wäre** (como en *Wenn ich du wäre …*). La oración principal tiene el infinitivo *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si pudiera decidir libremente, trabajaría en una empresa pequeña.","why":"*frei entscheiden können* → **könnte** al final de la oración con *wenn*. Oración principal con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si tuviéramos hijos, solo tendría que trabajar media jornada.","why":"*Kinder haben* con *wir* → **hätten**. El recuadro deja **müsste** para el último hueco.","source":"k2","check":"*müsste* y *würde* son alemán correcto en b, c y e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* está igual de bien). El recuadro solo dice qué tres huecos llevan *würde* y cuál lleva *müsste*; esta clave es el reparto más probable. Pregunta a tu profesor cuál quiere el libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Tengo que darme prisa por mi trabajo.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Reescribe las respuestas con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Porque mi novia es impuntual.","why":"*wegen* + sustantivo se convierte en *weil* + una oración con verbo; el verbo (*ist*) va al final.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Porque hace mal tiempo.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; después de *weil* el verbo va al final.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Porque tengo una cita importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (acusativo después de *haben*); verbo al final.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa: wegen – weshalb – weil – deswegen – denn. Una palabra puede usarse más de una vez.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Lo entiendo mal por su pronunciación.","why":"Sigue un sustantivo (*seiner Aussprache*, genitivo), no una oración → la preposición **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Algún día me gustaría viajar a Italia, porque me gustaría ver el mar.","why":"El verbo se queda en 2.ª posición después del hueco (*ich möchte*) → **denn**. Con *weil* iría al final.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Tengo que mejorar mi comprensión auditiva, por eso veo muchas películas.","why":"La segunda parte es la consecuencia, y el verbo va justo después del hueco (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mis hijos aprendieron alemán rápido porque en el jardín de infancia siempre están con niños suizos.","why":"El verbo está al final (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"¿Por qué escribes las palabras en tarjetitas?","why":"Hace falta una palabra interrogativa: **Weshalb** significa *warum* (por qué)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mi hermana ya habla alemán casi con fluidez, por eso puede ayudarme a aprender alemán.","why":"Consecuencia, y el verbo va justo después del hueco (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"En el curso de idiomas. Completa: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"No pude hacer el último ejercicio porque no lo entendí.","why":"El verbo está al final (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"En la inscripción no había nadie. Por eso volví a casa.","why":"Una frase nueva que da la consecuencia, con el verbo justo después del hueco (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Por mis buenas notas no tuve que hacer ninguna prueba al comienzo del curso.","why":"Sigue un grupo nominal (*meiner guten Noten*, genitivo plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Hay un curso de idiomas extra porque se han inscrito muchísimos participantes.","why":"El verbo está al final (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ayer, por desgracia, no pude venir al curso por mi dolor de muelas.","why":"Sigue un grupo nominal (*meiner Zahnschmerzen*, genitivo plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"¿Quién encuentra las mejores excusas? Elige una situación y escribe. Cada respuesta modelo es solo una posibilidad.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Por desgracia no pude ordenar la cocina porque de repente tuve un fuerte dolor de espalda. Tuve que acostarme. Por eso vi una película.","why":"Usa *weil* (verbo al final: *hatte*) y *Deswegen* (verbo justo después: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Por una gripe no fui al examen final. Tenía fiebre alta, por eso me quedé en la cama.","why":"Usa *wegen* + genitivo (*einer Grippe*) y *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"¡Lo siento muchísimo! Por desgracia he llegado tarde, porque había un accidente en la autopista. Por el atasco perdí dos horas.","why":"*denn* deja el verbo en 2.ª posición (*war*). *wegen des Staus*: genitivo de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (oraciones condicionales, también las irreales con Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, diccionario de conectores: wenn (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, diccionario de conectores: weil (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, diccionario de conectores: denn (causal, el verbo se queda en 2.ª posición)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va delante del verbo o en medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Crecer con varios idiomas · lectura, mensaje de foro, crucigrama, palabras favoritas","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Dos o tres idiomas en una familia: ¿sin problema?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"¿Quién dice qué? Lee los tres textos y escribe el nombre de la persona que dice cada frase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“Los niños quieren hablar el mismo idioma que sus amigos.” – Janusz","why":"Janusz (texto B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“Está bien hablar varios idiomas muy bien, ¿no?” – Yara","why":"Yara (texto C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“Mis hijos cambian entre dos idiomas.” – Amira","why":"Amira (texto A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Es la única que habla de sus propios hijos."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"¿Qué es correcto? Vuelve a leer los textos. Escribe *richtig* (correcto) o *falsch* (falso) después de cada frase; en el libro solo marcas las correctas.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Los hijos de Amira hablan árabe mejor que alemán. → correcto","why":"En casa la familia siempre habla árabe: *Darum können das die Kinder viel besser.* (Su alemán aquí es el alemán suizo.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"En la familia de Amira solo se habla alemán. → falso","why":"Justo lo contrario: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz estudió alemán durante seis años. → falso","why":"Tenía seis años cuando la familia se mudó (*als ich sechs Jahre alt war*), y al cabo de un año hablaba alemán estándar con fluidez."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz y su hermana no querían hablar polaco con sus padres. → correcto","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara habla tres idiomas con fluidez. → correcto","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* El alemán es su cuarto idioma y todavía no lo habla bien."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara va a empezar a aprender alemán también pronto. → falso","why":"No va a empezar pronto (*bald*): ya lleva dos años aprendiendo alemán (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Escribir un mensaje de foro. Has visto un debate de televisión sobre crecer con varios idiomas. En el foro en línea del programa encuentras esta opinión:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Toma notas sobre las cuatro preguntas. Bastan notas breves, sin frases completas. Las notas modelo son una posibilidad.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Sí: el hijo de mi vecina – italiano con su madre, alemán suizo en el colegio","why":"Solo notas: un nombre o una persona, y qué idiomas en qué sitio."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"aprender dos idiomas sin curso, contacto con la familia en el extranjero, ventajas en el trabajo","why":"Reúne dos o tres ventajas; las necesitas para *Ich finde es sehr gut, dass …* en b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mezclar los idiomas, un idioma es más débil, mucho trabajo para los padres","why":"Estas van en *Es könnte schwierig sein, dass …* y *Auf der anderen Seite …* en b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – los niños aprenden bien dos idiomas si sus padres hablan mucho con ellos","why":"Decide sí o no y da una razón: eso se convierte en *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Ahora escribe tu opinión sobre el tema (unas 80 palabras). Usa tus notas de a y algunas de las expresiones.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"No estoy de acuerdo con Sandra, porque muchos niños aprenden dos idiomas sin problemas. El hijo de mi vecina crece con italiano y alemán. Con su madre habla italiano y en el colegio alemán suizo. Me parece muy bien que aprenda dos idiomas tan pronto. Podría ser difícil que a veces mezcle los idiomas. Por otro lado, eso es normal en los niños pequeños. Lo más importante de todo es que los padres hablen mucho con el niño. Por eso cada progenitor debería hablar su propio idioma.","why":"Unas 85 palabras, con seis de las expresiones. *denn* mantiene el verbo en segunda posición (*lernen*); después de *Deswegen* el verbo va inmediatamente después (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Resuelve el crucigrama. Cada frase da la primera letra de la palabra que falta. Aquí no se muestra la cuadrícula: escribe la palabra completa. En la cuadrícula del libro la Ä ocupa una casilla.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Nuestro país de origen es España. Procedemos de España.","why":"*aus einem Land stammen* = proceder de un país (como *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda y Mike no se ven durante seis meses. Es una separación larga.","why":"*die Trennung* = separación, el sustantivo de *sich trennen*. *eine lange* → un sustantivo femenino."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"El alemán y el árabe no tienen la misma escritura.","why":"*die Schrift* = escritura, las letras con que se escribe un idioma. El árabe usa otro alfabeto."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter vive ahora en América. Desde que vive allí, ha cambiado mucho.","why":"*sich verändern* = cambiar (como persona). Perfekt: *hat sich verändert*. La Ä ocupa una casilla."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Ella escribe libros. Es autora de profesión.","why":"*Sie* → la forma femenina con *-in*: *der Autor → die Autorin*. Sin artículo después de *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Los niños no hacen los deberes. Por eso sus padres los regañan.","why":"*mit jemandem schimpfen* = regañar a alguien. Sujeto plural *die Eltern* → *schimpfen*. Después de *Deshalb* el verbo va inmediatamente después."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Solo lleva trabajando unos meses. Todavía tiene poca experiencia en su trabajo.","why":"*die Erfahrung* = experiencia. *wenig Erfahrung haben* = tener poca experiencia."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Ahora tenemos un caos. Todo está revuelto.","why":"*durcheinander sein* = estar revuelto, desordenado. Se escribe en una sola palabra."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Para Ye-Jon los sonidos P y F suenan igual. No sabe distinguirlos.","why":"*unterscheiden* = distinguir. Con *kann* el infinitivo va al final. *tönen* es la forma suiza de *klingen* (sonar)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Voy a Grecia de vacaciones, pero por desgracia no sé nada de griego.","why":"*Griechisch* = el idioma griego, con mayúscula. *kein Griechisch können* = no saber nada de griego."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Solo come verdura y arroz. Come exclusivamente verdura y arroz.","why":"*ausschliesslich* = exclusivamente, nada más que. Ortografía suiza con *ss*; en Alemania se escribe con la s aguda (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Palabra solución (la fila resaltada de la cuadrícula): lengua materna","why":"Cada palabra aporta una letra de la fila resaltada: stam**M**en, trenn**U**ng, schrif**T**, (T en la cuadrícula), veränd**E**rt, auto**R**in, (S en la cuadrícula), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"En casa con varios idiomas","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Mi palabra alemana más bonita","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Une cada foto con una palabra del recuadro. Los puntos de color del libro indican el artículo: azul = der, verde = das, rojo = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un postre de natillas con caramelo)","why":"Nombre suizo del crème caramel. *Chöpfli* es alemán suizo para “cabecita” (*Kopf*). Punto verde → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – estrella fugaz","why":"*der Stern* = estrella; *die Sternschnuppe* = estrella fugaz. Punto rojo → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – mariposa","why":"Palabra suiza para *der Schmetterling* (mariposa); el Duden la marca como *schweizerisch, sonst landschaftlich*. Punto azul → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"¿Por qué alguien podría encontrar precisamente estas palabras las más bonitas? ¿Qué piensas? Toma notas y luego habla de ellas. Las notas modelo son una posibilidad.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"tan colorida y ligera, recuerda al verano, gracioso: el animal no es un pájaro en absoluto","why":"Piensa en lo que te hace ver o sentir la palabra, y en cómo suena."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"dulce, recuerda a la infancia, suena gracioso y típicamente suizo","why":"*tönen* = forma suiza de *klingen* (sonar)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romántica, se puede pedir un deseo, suena suave","why":"Bastan notas breves: adjetivos y una razón."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Mi palabra favorita","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"¿Qué palabra alemana y qué palabra de tu lengua materna te gustan? ¿Por qué? Escribe un texto breve usando las expresiones. La respuesta modelo es una posibilidad.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Mi palabra alemana favorita es “gemütlich” (acogedor). Cuando oigo esta palabra, pienso en una tarde de invierno con té, velas y amigos. Por eso me parece tan bonita. Suena suave y cálida. En mi lengua materna, el inglés, no hay ninguna palabra con exactamente este significado. En inglés me gusta la palabra “sunshine”. Para mí es una palabra alegre, porque suena luminosa y amable.","why":"*Wenn …, dann* + verbo inmediatamente después (*denke ich*); *Deshalb* + verbo inmediatamente después (*finde ich*). Cambia por tu propia lengua materna y tus propias palabras.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Presenta tu texto en clase. En el modelo se muestra una posible forma de empezar.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Hoy me gustaría presentaros mi palabra favorita. Es la palabra “gemütlich”. …","why":"Empieza nombrando la palabra y luego lee tu texto de a. *euch* para los compañeros, *Ihnen* si hablas de usted."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va antes del verbo o en medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, diccionario de conectores: wenn (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Pedir aclaraciones con cortesía, aprender idiomas, buscar trabajo · Test de la lección 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (clave oficial de respuestas, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (oraciones condicionales, incluidas las irreales con Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"grammis, diccionario de conectores: weil (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, diccionario de conectores: denn (causal, el verbo se queda en 2.ª posición)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va delante del verbo o en el medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"grammis, diccionario de conectores: deshalb (consecuencia; sinónimos daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"grammis, diccionario de conectores: d(a)rum (consecuencia)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Perdone, ¿podría repetirlo, por favor?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Completa cada pregunta o frase con un comienzo del recuadro. Cada comienzo se usa una vez; el tachado se usa en el ejemplo.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"¿Qué significa la expresión “es eilig haben”?","why":"*Was bedeutet …?* pregunta por el significado de una palabra o expresión. (*es eilig haben* = tener prisa.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"¿Podría hablar más despacio, por favor?","why":"*Könnten Sie …* (Konjunktiv II) hace cortés la petición; el infinitivo *sprechen* va al final.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Lo siento, no he entendido esa palabra.","why":"Perfekt: *habe … verstanden*; *das Wort* va primero para darle énfasis, así que el verbo *habe* va justo después.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"¿Cómo dice? ¿Podría repetirlo, por favor?","why":"Petición cortés con *Könnten Sie …*; *wiederholen* (repetir) va al final.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"¿Sabe si aquí también hay cursos de integración?","why":"*ob* introduce una pregunta indirecta de sí o no, así que el verbo *gibt* va al final.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Perdone, ¿lo he entendido bien?","why":"Pregunta de sí o no en Perfekt: *habe* primero, *verstanden* al final.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"¿Me podría decir, por casualidad, dónde está el comedor universitario?","why":"Pregunta indirecta con *wo*: el verbo *ist* va al final. *die Mensa* = comedor universitario.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Completa los diálogos. Se dan las primeras letras impresas (y algunas letras dentro de las palabras); escribe completas las palabras que faltan.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"¿Cómo dice? No he entendido la última palabra.","why":"Perfekt: *habe* en 2.ª posición después de *Das letzte Wort*, *verstanden* al final.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Perdone, aquí hay mucho ruido. ¿Podría repetir la hora de la cita, por favor?","why":"Petición cortés: *Könnten Sie* … infinitivo *wiederholen* al final. Aquí *der Termin* = la hora de la cita.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"¿Puedo preguntarle algo? – Sí, claro. – ¿Sabe si en el tren de las 14.33 a Ginebra también hay un bistró o un restaurante?","why":"*Darf ich Sie etwas fragen?* abre la conversación con cortesía; *ob* inicia una pregunta indirecta de sí o no, así que *gibt* va al final.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Forma palabras con las sílabas del recuadro y completa las frases. Las sílabas tachadas (Men, sa) se usan en el ejemplo.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Mi coche se ha vuelto a estropear. ¿Me podrías dar otra vez el número de teléfono de tu buen mecánico, por favor? Esta vez quiero apuntarlo enseguida en mi agenda de direcciones para no volver a perderlo.","why":"Me-cha-ni-ker (persona que repara coches) y auf-schrei-ben (infinitivo al final después de *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"¿Qué significa la expresión “eine Entscheidung treffen”? Nunca la he oído.","why":"Aus-druck: *der Ausdruck* = expresión; *der* y *Den* muestran que es masculino. (*eine Entscheidung treffen* = tomar una decisión.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Por desgracia, a menudo olvido palabras alemanas importantes. Necesito más tiempo para repasar.","why":"Wie-der-ho-lung: *zur* = *zu der*, así que sigue un sustantivo femenino: *die Wiederholung* (repaso, repetición).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Aprender idiomas extranjeros, pero ¿cómo?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Aprender idiomas extranjeros, pero ¿cómo?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"¿Quién dice qué? Lee los tres textos y escribe la letra del texto (A, B o C) después de cada frase.","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"A menudo escucho a otras personas. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"Aprendo palabras de camino a la escuela. → A (Mila)","why":"Mila saca sus tarjetas de vocabulario durante la hora de tren hasta la escuela.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Después de la escuela me gustaría trabajar en Inglaterra. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Veo mucha televisión en alemán. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Escribo tarjetas de vocabulario. → A (Mila)","why":"Mila escribe la palabra extranjera en un lado de la tarjeta y la traducción en el otro.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Escribe la segunda frase: empieza con la palabra dada (Deshalb, Darum …) y usa las palabras entre paréntesis. El verbo va justo después de la palabra inicial.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Por eso repasa las palabras nuevas con tarjetas de vocabulario.","why":"*Darum* ocupa la posición 1, así que después va el verbo conjugado *wiederholt* y luego el sujeto *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Por esta razón tiene muchos pódcasts en su móvil.","why":"*Aus diesem Grund* ocupa la posición 1, como *deshalb*: después el verbo *hat* y luego *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Por eso quiere hablar bien inglés.","why":"*Deswegen* + verbo modal *will* en 2.ª posición, infinitivo *sprechen* al final.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Por ello ve mucha televisión en alemán.","why":"*Daher* significa lo mismo que *deshalb*; el verbo *schaut* va justo después.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Por esta razón simplemente escucha a los suizos en todas partes, todo el tiempo.","why":"*zuhören* es separable: *hört … zu*. El enunciado muestra *zugehört*, así que el Perfekt *hat … zugehört* (como en el texto de Danila) también es correcto.","source":"hueber","check":"La clave oficial da el presente (*hört … zu*), aunque el enunciado muestra el participio *zugehört*. Las dos frases son alemán correcto; pregunta a tu profesor cuál quiere el libro."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test de la lección 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa el texto de Arif. El libro da la primera letra y algunas letras dentro de cada palabra; escribe la palabra completa.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… y nuestra lengua materna es el árabe.","why":"*die Muttersprache* = la primera lengua, con la que creces."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Por eso quiero mejorar mi alemán.","why":"El patrón de letras (D, e, e) encaja con *Deswegen*; expresa la consecuencia, y el verbo *möchte* va justo después.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Claro que para entonces todavía no hablaré alemán con fluidez.","why":"*fliessend* = con fluidez. Ortografía suiza con *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Sobre todo la escritura y la pronunciación me parecen difíciles …","why":"*die Aussprache* = pronunciación (*aussprechen* = pronunciar)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… y tampoco entiendo todavía todas las expresiones.","why":"*der Ausdruck, die Ausdrücke* = expresión, expresiones; *alle* exige el plural."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Escribe oraciones condicionales irreales con *wenn* y el Konjunktiv II (*wäre, hätte, könnte, müsste* o *würde* + infinitivo).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Si mi inglés fuera mejor, podría ayudarte con los deberes.","why":"*sein* → **wäre** al final de la oración con *wenn*; *können* → **könnte**, y la oración principal empieza con el verbo.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Os entendería mejor si no hablarais todos a la vez.","why":"Primero la oración principal; *würde* + infinitivo en ambas partes. En la oración con *wenn*, *würdet* va al final.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Tendría más tiempo libre si no tuviera que trabajar tanto.","why":"*haben* → **hätte**, *müssen* → **müsste** (al final de la oración con *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa con una palabra del recuadro. Cada palabra se usa una vez; la tachada se usa en el ejemplo (la respuesta del ítem a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"¿Por qué quiere Costa ser técnico en mecatrónica? – Porque le interesan los coches.","why":"Hace falta un interrogativo; **Weshalb** = *warum* (por qué). La respuesta impresa empieza con *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Por sus buenos conocimientos de alemán encontró enseguida un puesto de aprendiz.","why":"Sigue un grupo nominal (*seiner guten Deutschkenntnisse*, genitivo plural) → la preposición **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Solo tiene 17 años. Por eso todavía vive con sus padres.","why":"Una consecuencia, y el verbo va justo después del hueco (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Ahora ahorra dinero, porque después de la formación le gustaría tener un piso propio.","why":"Una razón, y el verbo se queda en 2.ª posición (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"¿Cómo se puede decir de otra manera? Completa la segunda expresión. El libro da algunas letras; escribe las palabras completas.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Tengo una pregunta. – ¿Puedo preguntarle algo?","why":"Una forma cortés de empezar una pregunta: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"¿Podría decirlo otra vez, por favor? – ¿Podría repetirlo, por favor?","why":"*wiederholen* = repetir = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"¿Qué quiere decir con …? – ¿Qué significa …?","why":"*Was bedeutet …?* pregunta por el significado, como *Was meinen Sie mit …?*","check":"Las letras de este hueco se leen mal en la foto; *Was bedeutet …?* encaja con ellas y es la expresión del ejercicio 13. Pregunta a tu profesor si tu libro muestra otra cosa."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Perdón. / Disculpe. – Lo siento.","why":"*Tut mir leid* = lo siento, otra forma de disculparse."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Enfoque en el trabajo: buscar empleo","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf busca un nuevo trabajo de peluquero. Lee un folleto con consejos para buscar empleo. Lee los consejos y escribe la letra del título correspondiente (A–E) después de cada párrafo.","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Párrafo 1 (una lista de personas que conoces) → C, Tu red personal de contactos","why":"Amigos, compañeros y antiguos empleadores forman tu red personal de contactos.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Párrafo 2 (tu propio anuncio de empleo en internet) → A, Anuncio de búsqueda de empleo en línea","why":"*das Stellengesuch* = un anuncio en el que buscas trabajo; aquí, en un portal de internet.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Párrafo 3 (una candidatura breve a la empresa que deseas) → E, Candidatura espontánea","why":"Te presentas a una empresa que no ha publicado ninguna oferta: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Párrafo 4 (presentar candidaturas por teléfono) → D, Candidatura por teléfono","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Párrafo 5 (analizar ofertas de empleo en internet) → B, Ofertas de empleo","why":"*das Stelleninserat* (suizo) = un anuncio de empleo de una empresa.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf ha decidido tomar la iniciativa y ha escrito un anuncio de búsqueda de empleo. Lee su texto y busca: quién es Yusuf y cómo es, qué sabe hacer y qué busca. Escribe las palabras correspondientes para cada pregunta.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"un peluquero comprometido, creativo y flexible, de 24 años","why":"Quién es (profesión, edad) y cómo es (adjetivos).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"seis años de experiencia profesional, varias formaciones continuas en asesoría de estilo","why":"Lo que ofrece: experiencia y formación.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"un reto en el que pueda aprender cosas nuevas y seguir especializándose","why":"La última frase: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Publica un anuncio de búsqueda de empleo en internet. Buscas un nuevo trabajo. Haz una tabla con tres columnas (¿Quién soy y cómo soy? ¿Qué sé hacer? ¿Qué busco?) y luego escribe un texto de perfil como el de Yusuf en 2. La respuesta modelo es una posibilidad.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"¿Quién soy y cómo soy? flexible, con capacidad de trabajo en equipo, fiable, sociable | ¿Qué sé hacer? tratar bien a los clientes, buenos conocimientos de informática, alemán e inglés con fluidez | ¿Qué busco? un trabajo a tiempo parcial a partir del mes que viene, un equipo internacional","why":"Bastan unas pocas palabras clave por columna; usa las expresiones del recuadro.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"¿Busca una vendedora fiable, sociable y con capacidad de trabajo en equipo? Trato bien a los clientes, tengo buenos conocimientos de informática y hablo alemán e inglés con fluidez. Busco un trabajo a tiempo parcial en un equipo internacional a partir del mes que viene.","why":"Los mismos tres pasos que Yusuf: quién eres, qué sabes hacer y qué buscas. *die* en la oración de relativo se refiere a *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Gramática","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"¿Deseo y realidad?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina tiene que hacer una cosa, pero preferiría hacer otra. Escribe lo que preferiría hacer con *würde* + las palabras entre paréntesis (con *lieber*, o *gern* en el ítem 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Pero preferiría escuchar música.","why":"*würde* en 2.ª posición, *lieber* = más bien (preferencia), infinitivo *hören* al final.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Pero preferiría hablar por teléfono con su amiga.","why":"*würde* + *lieber* + infinitivo al final.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Pero preferiría jugar a juegos de ordenador.","why":"*würde* + *lieber* + infinitivo al final.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Pero le gustaría leer hasta tarde por la noche.","why":"El libro muestra *gern*: *würde* + *gern* + infinitivo (un deseo), con *aber* después del verbo.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Pero preferiría ir a bailar.","why":"*würde* + *lieber*; los dos infinitivos *tanzen gehen* van al final.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Reescribe las frases de a como oraciones condicionales irreales: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Si Nina no tuviera que estudiar para un examen de idiomas, escucharía música.","why":"*muss* → **müsste** al final de la oración con *wenn*; la oración principal empieza con *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Si Nina no tuviera que ordenar su ropa, hablaría por teléfono con su amiga.","why":"*müsste* + infinitivo *aufräumen*: en la oración con *wenn*, *müsste* va al final.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Si Nina no estuviera trabajando en el ordenador, jugaría a juegos de ordenador.","why":"La clave acepta *arbeiten würde* o *arbeiten müsste* en la oración con *wenn*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Si Nina no tuviera mañana una cita muy temprano, leería hasta tarde por la noche.","why":"*hat* → **hätte**, al final de la oración con *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Si Nina no pasara la tarde con sus padres, iría a bailar.","why":"*würde* + infinitivo en ambas partes; *verbringen würde* al final de la oración con *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Completa con *darum*, *weil* o *wegen*. Cada palabra se usa dos veces.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Muchos alemanes no notan los errores de gramática de Majid porque tiene muy buena pronunciación.","why":"Una razón, y el verbo *hat* está al final → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko no aprobó el examen, por eso ahora quiere hacer un curso intensivo.","why":"Una consecuencia, y el verbo *will* va justo después del hueco → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan quiere trabajar como médico en un hospital alemán, por eso necesita muy buenos conocimientos de alemán.","why":"Consecuencia + verbo justo después del hueco (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla es directiva y no puede asistir con regularidad al curso de alemán por sus muchas conferencias.","why":"Sigue un grupo nominal (*ihrer vielen Konferenzen*, genitivo plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"A Boris lo reconocen enseguida como ruso por su acento.","why":"Grupo nominal en genitivo (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"A Anja le gustaría aprender árabe porque la escritura árabe le parece muy bonita.","why":"Razón con el verbo *findet* al final → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Vocabulario","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa el texto de Ferdez con las palabras del recuadro. Cada palabra se usa una vez; la tachada se usa en el ejemplo. La hoja usa la ortografía alemana con la s aguda (Eszett); aquí, la ortografía suiza con *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"En macedonio se usa el alfabeto cirílico. Por eso al principio no me resultó fácil escribir en alemán.","why":"*die kyrillische Schrift* = el alfabeto cirílico."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Vivo en Baviera desde hace ocho años. Ahora ya hablo alemán con fluidez, creo.","why":"*fliessend Deutsch sprechen* = hablar alemán con fluidez."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"¡Pero mis compañeros del norte de Alemania dicen que tengo acento bávaro!","why":"*einen … Akzent haben* = tener acento; *einen bayerischen* → sustantivo masculino."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Cuando despotrico en bávaro, mis compañeros se mueren de risa.","why":"*schimpfen* = refunfuñar, despotricar; *ich schimpfe* al final de la oración con *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Cuando comparo entre sí el alemán, el macedonio y el albanés, me doy cuenta de …","why":"*miteinander vergleichen* = comparar entre sí; *ich vergleiche* al final de la oración con *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… que no todas las palabras se pueden traducir realmente bien al otro idioma. Hoy me siento en casa en Macedonia y en Alemania.","why":"*in eine Sprache übersetzen* = traducir a un idioma; el infinitivo va delante de *kann*, al final de la oración con *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"¿Qué significa el refrán “Lügen haben kurze Beine” (la mentira tiene las patas cortas)? Escribe A o B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: La verdad siempre sale a la luz enseguida. Por eso no hay que mentir.","why":"Una mentira no llega lejos, como alguien con las piernas cortas: pronto se descubre. B es un chiste sobre el sentido literal de las palabras."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"¿Qué palabra del recuadro podría sustituir a la palabra subrayada? Escríbela. Cada palabra se usa una vez; la tachada se usa en el ejemplo. Las palabras subrayadas aparecen en negrita.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Yo, en cambio, nací en Maguncia.","why":"*allerdings* = *aber*: matiza lo que se ha dicho antes."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Mis padres siempre hablaban alemán conmigo, por eso, por desgracia, no sé hablar farsi.","why":"*deswegen* = *deshalb* (consecuencia, el verbo va justo después).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Ahora hago un curso de idiomas. Creo que el farsi es tan difícil como el alemán.","why":"*ebenso … wie* = *genauso … wie* = tan … como."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"¡Sobre todo la escritura! Soy de los que tienen que apuntar todas las palabras nuevas.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = apuntar algo."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"Eso es difícil cuando tienes que hacerlo en una escritura que solo vas aprendiendo poco a poco.","why":"*allmählich* = despacio, paso a paso, poco a poco."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"La pronunciación tampoco es fácil. Hay un sonido, “gh”, que no sé pronunciar correctamente.","why":"*korrekt* = *richtig* = correctamente."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Algún día lo conseguiré, ¡al menos eso espero!","why":"*irgendwann* = en algún momento, algún día = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Lectura","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Lee las respuestas a la encuesta “¿Es importante aprender alemán?” y elige el final correcto para cada frase. Escribe el final (o solo sus primeras palabras).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Quien habla bien inglés tiene que aprender bien alemán de todos modos.","why":"A Brad, cuya lengua materna es el inglés, le decían una y otra vez: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Por lo visto, los alemanes creen que sin un alemán perfecto no tienes conocimientos profesionales.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena espera encontrar un trabajo en Austria con el certificado de alemán.","why":"Alena espera tener buenas oportunidades *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Como polaca, Ewa quiere saber alemán, porque Alemania y Polonia tienen una historia común.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"A Ewa le parece una pena que no muchos alemanes se interesen por el polaco.","why":"Ewa desearía que más alemanes se interesaran por el polaco."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha aprendió alemán de su marido.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Tiene problemas porque no entiende lo bastante bien a los profesores.","why":"Con el tutor de la clase y en las reuniones de padres tiene *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Para el permiso de trabajo se esperan buenos conocimientos de alemán.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah quiere saber bien alemán porque vive en Alemania.","why":"Quiere saber la lengua *des Landes …, in dem ich lebe*; su alemán ya le basta para los pacientes."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha aprende alemán por sus hijos.","why":"Sus hijos se quejaban de que su alemán era muy malo, y ahora la ayudan a aprender."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Expresión oral","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"¿Qué respuesta encaja mejor? Escribe el número de la respuesta (1–6) después de cada frase. (El ejercicio 6 de esta página es de comprensión auditiva y se omite.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Me llamo Kranitzky-Krampe. → 5 Perdone, ¿cómo ha dicho que se llama?","why":"Un nombre largo y poco común: vuelves a preguntar."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Para la ropa también se puede decir “Klamotten”. → 4 Nunca he oído esa palabra.","why":"Una palabra nueva (coloquial): *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"¿Qué significa esta palabra? → 1 Me temo que yo tampoco lo sé.","why":"Una respuesta a una pregunta que no sabes contestar."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Ahí tuve mucha suerte. → 6 ¿Lo he entendido bien? ¿Tuviste suerte?","why":"*Schwein haben* (coloquial) = tener suerte; compruebas que lo has entendido."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"¿Podría hablar más despacio, por favor? → 3 Vale, lo intentaré.","why":"Una respuesta a una petición."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Escribe las preguntas indirectas con las palabras entre paréntesis. En una pregunta indirecta el verbo va al final.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"¿Puede decirme adónde tengo que llevar la basura?","why":"*wohin* inicia la pregunta indirecta; el verbo conjugado *muss* va al final."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"¿Puede decirme, por favor, dónde le duele?","why":"Pregunta del médico: *wo* + sujeto + verbo al final (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"¿Sabe usted por casualidad si el tren va a Berlín?","why":"Una pregunta de sí o no se vuelve indirecta con *ob*; el verbo *fährt* va al final."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Expresión escrita","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Elige un idioma que te gustaría aprender y escribe un mensaje a la escuela de idiomas: qué idioma, cuándo y cuántas veces por semana tienes tiempo, qué fechas y horarios de curso ofrecen, el precio y la duración del curso; pide una respuesta y usa un saludo y una despedida adecuados. La respuesta modelo sigue la clave oficial.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Estimados señores: Me gustaría aprender griego moderno. Tengo tiempo de lunes a jueves por las tardes y podría ir dos veces por semana. Por favor, comuníquenme en qué horarios ofrecen un curso de griego moderno. También necesitaría saber cuánto cuesta el curso y cuánto dura. Les agradecería una breve respuesta. Atentamente, …","why":"Carta formal: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Las preguntas son indirectas (*zu welchen Zeiten …, wie viel …, wie lange …*): verbo al final."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Infinitivo con zu, la carta de presentación, charla informal sobre el trabajo · Test de la lección 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (clave oficial de soluciones, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (verbos modales sin zu; brauchen con zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (oraciones de infinitivo con zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu entre la partícula y el verbo: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (oración con dass o zu + infinitivo)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (Präposition, con genitivo)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (las preposiciones y los casos que rigen)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"¡Empieza de una vez a escribir candidaturas!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Por desgracia, no tengo tiempo …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Completa cada frase con un verbo del recuadro. Cada uno se usa una vez; el tachado se usa en el ejemplo.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"No os olvidéis de apagar la cocina, por favor.","why":"*ausschalten* es separable, así que *zu* va entre la partícula y el verbo: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"Tengo miedo de estar solo por la noche.","why":"*Angst haben* + *zu* + infinitivo; *sein* es un verbo simple, así que *zu* va delante.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"No, no es demasiado estresante colaborar en un club.","why":"*Es ist* + adjetivo + *zu* + infinitivo. *mitarbeiten* es separable: *mit**zu**arbeiten*. (Aquí el primer *zu* significa “demasiado”.)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Lo siento, no tengo tiempo de explicarle el camino.","why":"*keine Zeit haben* + *zu* + infinitivo. *erklären* no es separable (*er-* es un prefijo inseparable), así que *zu* va delante.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Hoy no tengo ganas de acompañaros al entrenamiento.","why":"*keine Lust haben* + *zu* + infinitivo; *mitkommen* es separable: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"¿Qué expresiones van seguidas de *zu*? Escribe la expresión (el verbo o verbo + sustantivo/adjetivo) que exige *zu* en cada frase de a.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"No os olvidéis de apagar la cocina, por favor. → olvidar","why":"El verbo *vergessen* (aquí *Vergesst*) va seguido de *zu* + infinitivo.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"Tengo miedo de estar solo por la noche. → tener miedo","why":"*haben* + sustantivo (*Angst, Lust, Zeit, Interesse*) va seguido de *zu* + infinitivo.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"No, no es demasiado estresante colaborar en un club. → (no) es (demasiado) estresante","why":"*Es ist* + adjetivo va seguido de *zu* + infinitivo.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Lo siento, no tengo tiempo de explicarle el camino. → (no) tener tiempo","why":"*Zeit haben* (aquí *keine Zeit*) va seguido de *zu* + infinitivo.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Hoy no tengo ganas de acompañaros al entrenamiento. → (no) tener ganas","why":"*Lust haben* (aquí *keine Lust*) va seguido de *zu* + infinitivo.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"¿Dónde va *zu*? La tabla tiene tres columnas: el comienzo de la frase, la parte central y luego el verbo con *zu*. Pon en ella las frases de a con verbo separable (2, 4, 6) y escribe la última columna. Las partes del verbo están entre paréntesis.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"No olvidéis, por favor, | la cocina | apagar.","why":"Verbo separable: *zu* va entre *aus* y *schalten*, y todo se escribe en una sola palabra.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"No, no es demasiado estresante | en un club | colaborar.","why":"Verbo separable: *mit* + *zu* + *arbeiten*, escrito en una sola palabra.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Hoy no tengo ganas | al entrenamiento | de ir con vosotros.","why":"Verbo separable: *mit* + *zu* + *kommen*, escrito en una sola palabra.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"¿Qué es correcto? Escribe *zu* si la frase necesita *zu*, o *–* (un guion) si no necesita nada.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"¿No le gustaría a usted también trabajar en la profesión de sus sueños?","why":"Después de un verbo modal (*möchten*), el infinitivo nunca lleva *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Podría imaginarme perfectamente aprendiendo un oficio.","why":"*sich vorstellen können* introduce una segunda oración después de la coma, con *zu* + infinitivo. *könnte* solo pertenece a *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Con una formación de artesano se puede encontrar un buen puesto de trabajo.","why":"Verbo modal *kann* + infinitivo sin *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"¿Podría usted ayudarme a elegir profesión?","why":"*Könnten* es un verbo modal (Konjunktiv II de *können*): sin *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"Es bastante estresante informarse sobre las opciones profesionales.","why":"*Es ist* + adjetivo (*stressig*) + *zu* + infinitivo.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Completa con *zu*, o escribe *–* (un guion) donde no falta nada.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"¡No podemos olvidar el cumpleaños de la jefa!","why":"Verbo modal *dürfen* + infinitivo sin *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"No es fácil encontrar un puesto en el trabajo de tus sueños.","why":"*Es ist nicht leicht* + *zu* + infinitivo.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Lo que más me gustaría es trabajar en equipo.","why":"*würde* + infinitivo (Konjunktiv II) funciona como un verbo modal: sin *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"¿Tienes un momento para ayudarme con mi candidatura?","why":"*Zeit haben* + *zu* + infinitivo.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"¿Te puedes imaginar haciendo un aprendizaje en una oficina?","why":"*Kannst* es un verbo modal, así que no va nada: *vorstellen* se escribe en una sola palabra.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"¡Empieza de una vez a escribir candidaturas!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Escribe frases sobre tu vida laboral: combina una expresión del recuadro de la izquierda con una actividad del recuadro de la derecha. Las palabras tachadas se usan en el ejemplo. La respuesta modelo es una posibilidad.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"En mi vida laboral no quiero hacer siempre lo mismo. Espero trabajar con compañeros simpáticos. Disfruto aprendiendo cosas nuevas. Sé trabajar muy bien de forma autónoma. Es agotador tener poco tiempo libre. Me gustaría viajar medio año por el mundo.","why":"Después de *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* se usa *zu* + infinitivo (verbos separables: *zusammen**zu**arbeiten*). Después de *möchten, können, würde … gern*, sin *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Relaciona cada afirmación con un verbo del recuadro y escribe una frase con *zu* + infinitivo. El verbo tachado se usa en el ejemplo.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Te prometo que mañana te recojo.","why":"“Seguro” = una promesa: *versprechen*. *abholen* es separable: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"Tengo previsto encontrar un trabajo interesante.","why":"Un plan = *vorhaben*: *Ich habe vor, … zu finden.* La partícula *vor* va al final de la oración principal.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Puedo imaginarme aprendiendo un oficio.","why":"“¿Por qué no?” = te lo puedes imaginar: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"A finales de mes dejo de trabajar como enfermero.","why":"“Solo hasta final de mes” = dejar de hacer algo: *aufhören*, con *auf* al final de la oración principal, antes de la coma.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Encuentra nueve palabras más en la sopa de letras y ponlas en las ofertas de empleo A–C. Las palabras rodeadas con un círculo (*Bewerbung, Tätigkeit*) son los ejemplos. Escribe cada palabra en la forma que necesita la frase (los sustantivos con mayúscula).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Buscamos apoyo para nuestro servicio de transporte de pacientes, 15 horas por semana.","why":"*die Unterstützung* = apoyo, ayuda; aquí significa una persona que ayuda.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Requisito para el puesto: carné de conducir de categoría B","why":"*die Voraussetzung* = requisito, condición previa. *der Führerausweis* es la palabra suiza para el carné de conducir.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ conocimientos de primeros auxilios","why":"*Kenntnisse in* + dativo = conocimientos de.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"Le esperan: tareas interesantes, posibilidades de formación continua, un ambiente de trabajo agradable","why":"*Es erwarten Sie …* = “le esperan …”; *es* solo ocupa la posición 1, y el verbo concuerda con el sujeto en plural que sigue.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ tareas interesantes","why":"*die Aufgabe, die Aufgaben* = tarea(s); *interessante* indica plural.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Se valorará experiencia en comercio y ventas.","why":"*der Handel* = comercio; *im* = *in dem*. *von Vorteil* = una ventaja.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"Si tiene preguntas, diríjase por escrito o por teléfono a la Sra. Kleinert.","why":"*schriftlich oder telefonisch* = por escrito o por teléfono.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"¿Te gusta trabajar con madera?","why":"*sich beschäftigen mit* = ocuparse de, dedicarse a; *du beschäftigst dich*. Empieza la pregunta de sí o no, así que lleva mayúscula.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Envía hoy mismo tu documentación de candidatura a: Clemens Meier","why":"*die Bewerbungsunterlagen* (plural) = currículum, certificados y carta, todo junto.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"¡Empieza de una vez a escribir candidaturas!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Completa con la forma correcta de *brauchen* o *müssen*. Consejo: *brauchen* va con *zu* + infinitivo y una negación o *nur*; *müssen* nunca lleva *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"Tus notas son muy buenas. De verdad, no tienes por qué preocuparte por encontrar trabajo.","why":"Negación (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Si solo trabaja a tiempo parcial, no tiene que pasarse todo el día sentada delante del ordenador.","why":"El infinitivo *sitzen* no lleva *zu*, así que el verbo es *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Si queremos viajar tres meses al extranjero, tenemos que ahorrar mucho dinero ahora.","why":"Sin *zu* y sin negación: es una obligación, así que *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"El trabajo de mis sueños. Escribe frases con *brauchen … zu* + infinitivo (= no tener que / solo tener que).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"No tengo que encargarme de tareas aburridas.","why":"*brauchen* en 2.ª posición, *zu übernehmen* al final. Aquí *übernehmen* no es separable, así que *zu* va delante.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"No tengo que hacer horas extra.","why":"*keine* + *brauchen … zu* = ninguna obligación.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Solo tengo que trabajar cuando me apetece.","why":"*nur brauchen … zu* = solo tener que. *zu arbeiten* cierra la oración principal antes de la oración con *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"No tengo que trabajar con compañeros antipáticos.","why":"*zusammenarbeiten* es separable: *zusammen**zu**arbeiten*, en una sola palabra.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"Una carta de presentación","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Lee las partes de la carta y ordénalas: escribe el número (1–8) de cada parte. Aquí las partes llevan las letras A–H en el orden en que las imprime el libro; B es el ejemplo.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"Me resulta fácil aprender cosas nuevas. Además, disfruto asesorando a los clientes. Por eso me gustaría trabajar con ustedes como vendedor. → 5","why":"Por qué quieres el puesto va después de tu experiencia (4) y antes de la petición final (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Saludos cordiales / Tibor Kelemen → 7","why":"La despedida y tu nombre van después de la última frase.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"He leído su anuncio con gran interés y me presento como candidato a la vacante de vendedor de bicicletas eléctricas. → 3","why":"La primera frase después del saludo dice a qué puesto te presentas.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Me encantaría recibir una invitación a una entrevista personal. → 6","why":"La última frase habitual de una carta de presentación.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Anexos: currículum, certificados de trabajo → 8","why":"Los *Beilagen* (anexos) van al final del todo, debajo del nombre.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Estimados señores y señoras → 2","why":"El saludo va después de la línea de asunto. En Suiza no se pone coma detrás.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Como podrán ver en mi documentación, tras terminar la secundaria hice la formación de mecánico de bicicletas en la empresa «Velo-XL». Después trabajé dos años como empleado en una tienda de bicicletas y también pude adquirir mi primera experiencia en ventas. → 4","why":"Tu formación y tu experiencia van después de la frase inicial.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"¡Empieza de una vez a escribir candidaturas!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Completa la carta de presentación. Encontrarás ayuda en a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Estimada Sra. Zerlich","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: la terminación depende de la persona.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"He leído con gran interés su oferta de empleo y me presento como candidata al puesto de fisioterapeuta.","why":"Expresión inicial fija de a; ocupa la posición 1, así que sigue el verbo *habe*.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Como podrá ver en mi documentación, tras mi formación como fisioterapeuta trabajé cuatro años en un hospital de Lodz, en Polonia.","why":"*etwas (Dativ) entnehmen* = ver algo en un documento, deducirlo de él: *meinen Unterlagen* es dativo plural.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Después trabajé dos años en la consulta Kunz & Rosenthal. Allí también pude adquirir experiencia en el campo de la medicina deportiva.","why":"*Erfahrungen sammeln* = adquirir experiencia.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"Mi lengua materna es el polaco. Pero también hablo muy bien alemán e inglés.","why":"*die Muttersprache* = lengua materna; *meine* porque es femenino.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"El puesto en una residencia de ancianos es algo completamente nuevo para mí. Disfruto mucho aprendiendo cosas nuevas. Además, me gusta cuidar de otras personas y me hace ilusión el contacto con los residentes.","why":"*Es macht mir Freude, … zu* + infinitivo, como en a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Me encantaría recibir una invitación a una entrevista personal.","why":"Frase final fija: *eine Einladung zu* + dativo.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Saludos cordiales, Alina Jankowska","why":"Despedida; ortografía suiza *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Elige una de las tres ofertas de empleo del Zirkus Tortellini y escribe una carta de presentación. Usa las partes de a y b. La respuesta modelo es una posibilidad.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Candidatura como acróbata / Estimado Sr. Tortellini / He leído con gran interés su oferta de empleo y me presento como candidata al puesto de acróbata en su circo. Como podrá ver en mi documentación, me formé como bailarina. Después bailé tres años en un teatro de Berna y allí adquirí mi primera experiencia sobre el escenario. Disfruto mucho actuando ante el público. Me imagino perfectamente viajando por Suiza con su circo. Me encantaría recibir una invitación a una entrevista personal. / Saludos cordiales / Lara Steiner / Anexos: currículum, certificado de trabajo","why":"Las mismas ocho partes que en a; cada una responde a un punto de la oferta (formación como bailarina, primera experiencia en un teatro). *auf**zu**treten*: *auftreten* es separable.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante su último año escolar …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Completa con *während* (durante), *innerhalb* (dentro de) o *ausserhalb* (fuera de), más la palabra entre paréntesis en la forma correcta. Las tres rigen genitivo.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Muchas gracias por su candidatura. Recibirá nuestra respuesta en el plazo de unas semanas.","why":"Un plazo = *innerhalb*; genitivo plural sin artículo: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Está llamando fuera de nuestro horario comercial. Este es de …","why":"Fuera de un período de tiempo = *ausserhalb*; genitivo plural *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"Mientras espera, puede tomarse un café si lo desea.","why":"Al mismo tiempo que = *während*; genitivo femenino *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"La empresa quiere mejorar sus resultados un 20 % en los próximos dos años.","why":"Un plazo = *innerhalb*; genitivo plural *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Completa la entrevista con las preposiciones de tiempo del recuadro. Cada una se usa una vez; *während* aparece dos veces en el recuadro. El *von … an* tachado se usa en el ejemplo.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"La tecnología siempre me ha interesado. Ya durante mis años de colegio trabajé para un electricista.","why":"*während* + genitivo (*meiner Schulzeit*) = durante.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Justo después del colegio hice unas prácticas en una gran empresa energética.","why":"*nach* + dativo (*der Schule*) = después de.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Pero ya durante el primer año se aprenden las cosas más importantes.","why":"*während* + genitivo *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Aun así, antes del examen final todavía tengo que estudiar mucho.","why":"*vor* + dativo (*der Abschlussprüfung*) = antes de; mayúscula al principio de la frase.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Desde la mañana hasta el final de la jornada recorro el recinto de nuestra empresa y reparo instalaciones.","why":"*von … bis* = desde … hasta; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"¿Qué experiencias has tenido como mujer en tu trabajo?","why":"*bei* + dativo (*deiner Arbeit*) = en, en el transcurso de.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"¡Solo positivas! Mis compañeros y yo quedamos a menudo por la tarde, o sea, fuera del horario de trabajo.","why":"*ausserhalb* + genitivo (*der Arbeitszeit*) = fuera de.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Práctica de examen: lee el correo electrónico y completa los huecos 1–6. ¿Qué opción (a, b o c) encaja mejor? Escribe la palabra (o su letra).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Muchas gracias por su candidatura como mecatrónico de automóviles.","why":"*Vielen Dank für* + acusativo.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Nos alegra su interés por nuestra empresa …","why":"*Interesse an* + dativo = interés por; *Ihr* concuerda con el neutro *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Por favor, avísenos en los próximos días …","why":"Un plazo con genitivo (*der nächsten Tage*) = *innerhalb*. *bis* necesitaría *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"… si puede venir a esta cita.","why":"Una pregunta indirecta de sí o no necesita *ob* (si).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Traiga también los siguientes documentos: el título de la escuela profesional en original y su certificado B2.","why":"Un certificado y un título son *Dokumente*; *Zeugnisse* no incluiría también el certificado B2, y *Sachen* es demasiado vago para una carta formal.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"Quedamos a su disposición para cualquier pregunta y para darle más información.","why":"Expresión fija: *jemandem zur Verfügung stehen* = estar a disposición de alguien.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante su último año escolar …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Relaciona cada pregunta u observación de una entrevista de trabajo con la respuesta (1–7). Escribe el número. (El ejercicio 13 es de comprensión auditiva y se omite.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Cuéntenos algo sobre usted, por favor. → 7 Bueno, soy mecánico de maquinaria de construcción y me estoy sacando el carné de conducir de categoría BE.","why":"Te presentas: tu profesión y lo que haces ahora.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"¿Qué tareas tenía con su último empleador? → 1 Era responsable del control de artículos de hogar, jardín y ocio.","why":"*zuständig sein für* = ser responsable de (tus tareas).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"¿Tiene otras habilidades? → 6 Sí, hablo tres idiomas.","why":"Una pregunta de sí o no sobre habilidades: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"¿Puede contarme más sobre sus conocimientos de informática? → 2 Conozco los programas habituales y el año pasado hice una formación en bases de datos de almacén.","why":"*beherrschen* = dominar; *sich weiterbilden* = hacer formación continua.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"¿Tiene alguna pregunta más? → 3 Sí, me gustaría saber qué tamaño tiene el almacén aquí.","why":"Una pregunta indirecta: *wie gross das Lager hier ist* (verbo al final).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Muchas gracias por venir, Sr. Trantow. → 4 Gracias a ustedes también.","why":"Devuelves el agradecimiento: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"¡Esto lo sé hacer! Completa las frases con información sobre ti. Las respuestas modelo son una posibilidad.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Ya durante el colegio trabajé a tiempo parcial en una cafetería.","why":"*während* + genitivo; Perfekt con el participio al final.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"Era responsable de la contabilidad en una pequeña oficina.","why":"*zuständig für* + acusativo.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Domino Excel y los programas de ofimática habituales.","why":"*beherrschen* + acusativo = dominar una habilidad o un idioma.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"También tengo muy buenos conocimientos de inglés e italiano.","why":"*Kenntnisse in* + dativo.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Me resulta fácil trabajar en equipo y acercarme a nuevos clientes.","why":"*Es fällt mir leicht* + *zu* + infinitivo; *zugehen* es separable: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Orientación profesional","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"¿Qué es correcto? Lee los textos. Escribe *richtig* (correcto) o *falsch* (falso) después de cada frase; en el libro solo marcas las correctas.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline no tiene ganas de estudiar en la universidad. → correcto","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Le resulta difícil planificar u organizar cosas. → falso","why":"Lo contrario: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"La semana que viene quiere informarse sobre formaciones comerciales. → correcto","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, sobre una profesión comercial.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos tenía pensado trabajar en el ámbito de la tecnología después del colegio. → correcto","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"Al principio le resultó difícil combinar sus áreas de interés. → correcto","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Esperaba disfrutar del aprendizaje como delineante de arquitectura paisajista. → falso","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = no se lo esperaba.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Escribe una frase con *zu* + infinitivo para cada indicación (a–e). Luego busca el consejo (1–5) que encaja; la solución muestra su número.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"No me cuesta levantarme temprano. → 4 ¿Qué tal un trabajo de panadero?","why":"*Ich finde es* + adjetivo + *zu* + infinitivo; *aufstehen* es separable: *auf**zu**stehen*. Los panaderos empiezan muy temprano.","source":"g4069","check":"La clave oficial escribe *Es fällt mir nicht schwer, früh aufzustehen*, que significa lo mismo; el enunciado *es nicht schwer finden* da *Ich finde es nicht schwer, …*. Las dos son correctas."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"Me apetece estar mucho tiempo de un sitio a otro. → 1 Podrías ser conductor de autobús.","why":"*Lust haben* + *zu* + infinitivo.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"Disfruto cocinando para los demás. → 5 Yo en tu lugar me haría cocinero.","why":"*Es macht mir Freude* + *zu* + infinitivo.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Me interesa desarrollar cosas nuevas. → 3 Mmm, difícil. ¿Quizás diseñador de moda?","why":"*Interesse haben (daran)* + *zu* + infinitivo; *daran* anticipa la oración con *zu*.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Palabras con -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Forma sustantivos terminados en *-ung* a partir de los verbos, con el artículo. (Las partes b–d son de comprensión auditiva y se omiten.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"experimentar → experiencia","why":"Raíz del verbo + *-ung*; los sustantivos en *-ung* siempre son femeninos: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"ser responsable de → responsabilidad","why":"Raíz *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"emplear / ocupar → empleo, ocupación","why":"Raíz *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"apoyar → apoyo","why":"Raíz *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Charla informal: hablar del trabajo","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Completa el diálogo de charla informal entre Bettina (○) y un amigo (◆) con las expresiones de los dos recuadros (aquí se muestran como uno solo). Cada expresión se usa una vez; la tachada se usa en el ejemplo.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Difícil. Sigo buscando un trabajo de traductora.","why":"Después de *Ich* va el verbo *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ Ya he escrito varias candidaturas, pero solo he recibido rechazos.","why":"Perfekt: *habe … geschrieben*, en paralelo con *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ ¿Nunca has pensado en hacerte autónoma? Muchos traductores lo hacen.","why":"*daran denken* + *zu* + infinitivo; *daran* remite a la oración con *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Sí, es verdad. Pero es superestresante estar siempre buscando encargos. Además, hay mucha competencia.","why":"*Es ist* + adjetivo + *zu* + infinitivo.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Pero ¿y tú qué tal? ¿Sigues teniendo tanto trabajo?","why":"La respuesta *Ja, leider* necesita una pregunta de sí o no.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Sí, por desgracia. En nuestra empresa ahora hay varias personas de baja. Tengo que sustituir a dos compañeros. ¡Y justo ahora, que tenemos tantos pedidos!","why":"*vertreten* = sustituir a alguien.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ ¿Y tú qué haces ahora exactamente?","why":"Una pregunta con palabra interrogativa (W-Frage): *Was* + verbo *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ ¿No es agotador ir siempre de obra en obra?","why":"*Ist das nicht anstrengend, … zu* + infinitivo?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ A veces sí, pero casi siempre disfruto del trabajo. Me llevo bien con los clientes y con los compañeros. Por cierto, mi empresa está buscando a alguien para la oficina. ¿No quieres presentarte?","why":"*mit jemandem gut zurechtkommen* = llevarse bien con alguien (separable).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ ¡Pero qué dices! Soy traductora. No me interesa un trabajo de secretaria.","why":"*Interesse an* + dativo (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ Vale, lo haré. Gracias por el consejo. Ay, lo siento, ahora tengo que irme.","why":"Una forma típica de terminar una charla informal.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Completa los anuncios breves. El libro da algunas letras de cada palabra; escribe la palabra completa.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Trabajar en las vacaciones semestrales: te buscamos como traductor/a de textos publicitarios breves.","why":"*der Übersetzer / die Übersetzerin* = traductor, traductora.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Trabajar como autónomo/a en la limpieza: en Putzfee.net puede ofrecer su servicio y buscar encargos.","why":"*der Auftrag, die Aufträge* = encargo, trabajo; *nach* + dativo plural añade *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Haga un curso de formación. Ofrecemos seminarios interesantes en los ámbitos de la tecnología y el comercio.","why":"*eine Fortbildung machen* = hacer un curso de formación.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"¡Porque la competencia no duerme!","why":"*die Konkurrenz* = la competencia (los rivales).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"¿Flexible y motivado/a? Buscamos personas que puedan sustituir por horas a nuestro personal de almacén.","why":"Verbo modal *können* + infinitivo *vertreten* (sin *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test de la lección 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa las frases. El libro da algunas letras de cada palabra; escribe la palabra completa.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"La empresa Müller & Müller es muy buena y por eso tiene muchos pedidos.","why":"*der Auftrag, die Aufträge* = pedido(s); *viele* exige el plural."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"La Sra. Brügger es responsable de 200 empleados.","why":"*die Verantwortung für* + acusativo = responsabilidad sobre."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"La empresa fabrica los muebles con madera suiza.","why":"*herstellen* = fabricar, producir; separable: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario trabaja de camarero en un restaurante.","why":"*der Serviceangestellte* = camarero (uso suizo); después de *als* sin artículo la terminación es *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter es responsable del control y la reparación de las máquinas herramienta.","why":"*zuständig sein für* = ser responsable de."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"La empresa Müller & Müller ofrece a sus empleados muchos cursos de formación.","why":"*die Fortbildung, die Fortbildungen*; *viele* exige el plural."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Reescribe cada frase con el comienzo dado, usando *zu* + infinitivo. Escribe solo la parte que va después de la coma.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"Disfruto trabajando con mis compañeros.","why":"*die Zusammenarbeit* → el verbo *zusammenarbeiten*, separable: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Podría imaginarme perfectamente trabajando como enfermero.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"El orientador profesional promete ayudar con la elección de profesión.","why":"*die Hilfe* → el verbo *helfen*: *zu helfen* al final.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Completa con *während*, *innerhalb* o *ausserhalb* más el artículo en la forma correcta (genitivo). El libro da la primera letra del artículo.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"Durante la entrevista, por supuesto, puede hacer preguntas.","why":"*während* + genitivo neutro: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Por favor, comuníquenos en el plazo de una semana si viene.","why":"*innerhalb* + genitivo femenino: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Puede localizarme por teléfono o, fuera del horario de oficina, por correo electrónico.","why":"*ausserhalb* + genitivo plural: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Relaciona cada pregunta con la respuesta (1–5). Escribe el número.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"¿Nunca has pensado en cambiar de trabajo? → 1 No, no me lo imagino.","why":"Una pregunta sobre una idea: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"¿Y tú qué haces ahora exactamente? → 4 Estoy terminando mi aprendizaje de pintor.","why":"Una pregunta con palabra interrogativa sobre tu trabajo necesita un hecho como respuesta."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"¿No es estresante trabajar de noche? → 2 No, no me lo parece.","why":"*Ist es nicht stressig …?* pide una opinión: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"¿Sigues teniendo tanto trabajo? → 3 Sí, tengo que sustituir a una compañera.","why":"Pregunta de sí o no; el motivo de tanto trabajo: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Enfoque en el trabajo: negociar","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Cuatro buenos consejos","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"¿Para qué son estos consejos? Lee el texto por encima y escribe la respuesta correcta. (Los ejercicios 2 y 3 de esta página son de comprensión auditiva y se omiten.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Para conversaciones con el empleador","why":"Los consejos tratan de cómo hablar de dinero en la entrevista de trabajo, con el jefe o la jefa de personal.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"¿Qué es correcto? Vuelve a leer. Escribe *richtig* (correcto) o *falsch* (falso) después de cada frase; en el libro solo marcas las correctas.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"Es tarea del jefe o la jefa de personal sacar el tema del sueldo. → correcto","why":"Consejo 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"En el nuevo puesto de trabajo recibe al principio el mismo sueldo que en la empresa anterior. → falso","why":"Consejos 2 y 3: tu último sueldo es solo la base; puedes pedir más.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Si quiere un sueldo más alto, debería dar buenos argumentos. → correcto","why":"Consejo 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Si el jefe o la jefa de personal no está de acuerdo con su propuesta, ya no puede hacer nada más. → falso","why":"Consejo 4: sé flexible y haz otras propuestas (formación pagada, más sueldo al cabo de seis meses).","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"Finalidad con um … zu y damit, en lugar de / sin, verbos con es, conversaciones de venta y reclamaciones · Test de la lección 6","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"No es fácil, pero vale la pena.","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"Completa el correo electrónico de Anna con las expresiones con *es* del recuadro. Cada una se usa una vez; *geht es* se usa en el ejemplo. Cuando una expresión lleva *…*, van otras palabras en medio: escribe las dos partes en los dos huecos.","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"Es verano, por todas partes se ven flores y estoy mucho al aire libre. ¡Me encanta esta estación!","why":"*es* + *sein* + una estación u hora del día: *Es ist Sommer / Nacht / vier Uhr*.","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"Es verdad que desde hace unos días llueve, pero el mal tiempo no me molesta.","why":"Los verbos del tiempo atmosférico siempre tienen *es* como sujeto. *Seit ein paar Tagen* está en la posición 1, así que *es* va después del verbo: *regnet es*.","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"Lo principal es que no haga frío.","why":"Tiempo atmosférico con un adjetivo: *es ist kalt / heiss*. *nicht* va delante de *kalt*.","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"Oye, ¡esta mañana he tenido una entrevista de trabajo! Fue realmente emocionante, …","why":"*es* general + *sein* + adjetivo, aquí en Präteritum: *Es war aufregend*.","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"… pero en realidad ha ido bastante bien. La gente es muy simpática y el trabajo es variado.","why":"*Es ist gut gelaufen* = ha ido bien (Perfekt con *sein*). *eigentlich* está en la posición 1, así que *ist es*.","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"Solo hay, por desgracia, un problema: ¡tengo que empezar a trabajar a las 7 (!) de la mañana! ¡Qué horror!","why":"*es gibt* + acusativo = hay: *Es gibt ein Problem*.","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"Ya sabes lo difícil que se me hace levantarme temprano.","why":"*Es fällt mir schwer, … zu …* = se me hace difícil … En la oración con *wie*, el verbo va al final: *wie schwer es mir fällt*.","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"Sobre todo en invierno, cuando todavía es de noche, …","why":"*Es ist dunkel* (hora del día, luz). En la oración con *wenn*, el verbo va al final: *wenn es noch dunkel ist*.","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"… entonces se me hace realmente difícil.","why":"*Es wird schwierig* = se vuelve difícil. *dann* está en la posición 1, así que *wird es*.","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"Es verdad que me gustó mucho la empresa, pero no sé si podré con lo de levantarme temprano. ¿Qué me aconsejas?","why":"*Es gefällt mir* = me gusta; en Perfekt: *Es hat mir gefallen*. Aquí *Mir* está en la posición 1.","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"P.D.: Ay, ya vuelve a ser la una de la madrugada.","why":"La hora: *Es ist ein Uhr*. *jetzt* está en la posición 1, así que *ist es*.","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"¿Quizás debería simplemente acostarme más temprano? Quién sabe, quizás vale la pena y de repente por la mañana siempre estoy en plena forma.","why":"*Es lohnt sich* = vale la pena. *vielleicht* está en la posición 1, así que *lohnt es sich*.","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"Clasifica las expresiones con *es* del ejercicio 1 en cuatro grupos. Escribe el grupo: *Allgemein* (general), *Tages-/Jahreszeiten* (horas del día y estaciones), *Wetter* (tiempo atmosférico) o *Befinden* (cómo está alguien).","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"Es verano. → horas del día y estaciones","why":"Una estación del año.","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"llueve → tiempo atmosférico","why":"Verbo del tiempo atmosférico.","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"hace frío → tiempo atmosférico","why":"La temperatura es tiempo atmosférico.","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"Fue (emocionante) → general","why":"*es* + *sein* + adjetivo sobre una situación.","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"ha ido (bien) → general","why":"Cómo ha ido algo: una expresión general.","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"Hay → general","why":"*es gibt* = hay.","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"lo difícil que se me hace → general","why":"*es fällt mir schwer* = se me hace difícil.","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"está oscuro → horas del día y estaciones","why":"Oscuro = hora del día.","source":"hueber","check":"La clave oficial pone *es ist dunkel* con las horas del día. También podrías verlo como tiempo atmosférico; pregunta a tu profesor si en tu clase lo clasificasteis de otra manera."},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"se vuelve difícil → general","why":"*es* + *werden* + adjetivo sobre una situación.","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"me ha gustado → general","why":"*es gefällt mir* = me gusta.","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"es la una → horas del día y estaciones","why":"La hora.","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"vale la pena → general","why":"*es lohnt sich* = vale la pena.","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"¿Dónde falta *es*? Lee el correo electrónico de Fatima. Vuelve a escribir cada frase de abajo con *es* en el lugar correcto. Una frase ya es correcta: en ese caso, escríbela sin cambios.","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"Espero que estéis todos bien.","why":"*Wie geht es euch?* → *dass es euch gut geht*: *es* es el sujeto de *gehen* en este sentido y no se puede omitir.","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"Desde que vivimos en Gossau han pasado muchas cosas.","why":"Sin *es*: *viel* es el sujeto, y la oración con *seit* ocupa la posición 1.","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"Ahora las cosas van bastante bien, pero al principio hubo muchos problemas.","why":"Dos huecos: *es läuft gut* (las cosas van bien) y *es gab* (había, Präteritum de *es gibt*). Con *jetzt* / *am Anfang* en la posición 1, *es* va después del verbo.","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"Para nuestros hijos fue especialmente difícil.","why":"*es* + *sein* + adjetivo: *es war schwer*.","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"Pero ahora ya está mucho mejor y se han acostumbrado a la vida aquí.","why":"*es ist besser*: la situación no tiene otro sujeto, así que hace falta *es*.","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"Bueno, ya son casi las 9.","why":"La hora: *es ist 9 Uhr*.","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"No es fácil, pero vale la pena.","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"¿Qué es correcto? Lee el texto sobre una tertulia en un pueblo y escribe la palabra que encaja en cada hueco. Las dos opciones aparecen encima de cada frase.","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"Al principio en realidad era un experimento y solo venían muy pocos participantes.","why":"*Heimweh* (nostalgia) no tiene sentido aquí; una idea nueva que puede funcionar o no es un *Experiment*.","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"Había como mucho de cinco a diez personas.","why":"*nur sehr wenige* → *höchstens* (como mucho), no *mindestens* (como mínimo).","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"Pero entretanto también vienen cada vez más suizos; ahora a menudo son incluso más de 30 personas por encuentro.","why":"*mittlerweile* = a estas alturas, entretanto (como *inzwischen*).","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"Todos ayudan gratis y así la tertulia funciona sin apoyo económico.","why":"*gratis* (gratis) → no hace falta dinero: *finanzielle Unterstützung*.","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"Completa las frases. El libro da algunas letras de cada palabra (aparecen encima de la frase); escribe la palabra completa.","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"Estoy triste porque no estoy en casa. Tengo nostalgia.","why":"*das Heimweh* = nostalgia (de casa); *Heimweh haben*.","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"Lo más importante al cocinar platos indios son las especias adecuadas.","why":"*das Gewürz, die Gewürze* = especia(s); en plural por *sind*.","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"Mis abuelos tenían varias tiendas. Eran comerciantes de éxito.","why":"*die Geschäftsleute* = plural de *der Geschäftsmann / die Geschäftsfrau*.","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"Nuestro vecino escucha música alta a cualquier hora del día. Nos molesta a todos, pero él no tiene ninguna consideración.","why":"*Rücksicht nehmen (auf)* = tener consideración (con).","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"Cuando uno se establece por su cuenta con un negocio, a menudo es un riesgo económico.","why":"*das Risiko* es neutro, así que *ein finanzielles Risiko*.","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"Mi tío tiene muchas buenas ideas. Resuelve casi cualquier problema.","why":"*ein Problem lösen* = resolver un problema; *er löst*.","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"Letras y sonidos: *b – p, g – k, d – t*. (Las partes a y b son de comprensión auditiva y se omiten.)","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"Completa la regla: ¿cómo se pronuncian *b, d, g* al final de una palabra? Fíjate en *halb, Geld, Tag*.","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"A final de palabra, *b, d, g* se pronuncian como *p, t, k*.","why":"*halb* suena como \"halp\", *Geld* como \"Gelt\", *Tag* como \"Tak\". Lo mismo pasa delante de otra consonante: *Erfolg*, *Auftrag*, *ab und zu*.","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Quiero estar en la tienda para poder esperar allí.","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Los objetivos de Margareta. Cada línea muestra un deseo (izquierda) y la misma idea como finalidad con *um … zu* (derecha). Rellena los huecos del lado que falte.","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"Quiere hacer una formación profesional. → para hacer una formación profesional.","why":"El deseo: *möchte* + infinitivo al final. *um … zu* quita el verbo modal.","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"Quiere ser más independiente. → para ser más independiente.","why":"*um* abre el grupo, *zu* + infinitivo lo cierra. *möchte* desaparece.","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"Quiere ganar dinero. → para ganar dinero.","why":"De vuelta al deseo: *Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"Quiere estar cerca de su novio. → para estar cerca de su novio.","why":"*um … zu sein*; *ihres Freundes* es genitivo después de *in der Nähe*.","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"¿Por qué hacen esto las personas? Elige del recuadro el objetivo que encaja con cada frase y añádelo como *um … zu* + infinitivo. *gesund bleiben* se usa en el ejemplo.","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Peter se levanta muy temprano de lunes a viernes para ser el primero en la oficina.","why":"Misma persona (Peter), así que *um … zu*; *sein* va al final con *zu*.","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"El fin de semana siempre voy al mercado para comprar ingredientes frescos y especias.","why":"Todo lo que pertenece a *kaufen* va delante de *zu kaufen*.","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"El señor Aryan va mañana a Ginebra para reunirse con un cliente importante.","why":"*um … zu treffen*; el complemento *einen wichtigen Kunden* va en medio.","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina hace un curso de formación profesional continua para tener mejores oportunidades en el mercado laboral.","why":"Misma persona (Sabina): *um … zu haben*.","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"¿Por qué vino Yaroslav a Suiza?","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"Lee el texto y completa los motivos con palabras del texto.","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"Su mujer puede vivir en una ciudad en el extranjero.","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"Sus hijos pueden ir a una buena escuela.","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"Todo el equipo de programadores está en Zug.","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Quiero estar en la tienda para poder esperar allí.","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"Reescribe los motivos de a como oraciones con *damit*: *Yaroslav ist in die Schweiz gekommen, damit …* El verbo va al final.","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav vino a Suiza para que su mujer pueda vivir en una ciudad en el extranjero.","why":"Persona distinta (su mujer), así que solo *damit*; *kann* va al final del todo.","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav vino a Suiza para que sus hijos puedan ir a una buena escuela.","why":"Persona distinta (sus hijos): *damit … besuchen können*.","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav vino a Suiza para que todo el equipo de programadores esté en Zug.","why":"Sujeto distinto (el equipo): *damit … ist*.","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"¿Por qué se levanta temprano Yaroslav? Fíjate en quién hace la segunda acción. Misma persona: escribe con *damit* y con *um … zu*. Persona distinta: solo funciona *damit*.","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav se levanta temprano para poder tomarse el café con calma.","why":"Misma persona (*er*). *will* se convierte en *kann* en la oración con *damit*; el verbo va al final.","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav se levanta temprano para tomarse el café con calma.","why":"Misma persona, así que *um … zu* también funciona: sin sujeto y sin *will*.","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav se levanta temprano para que luego el baño esté libre para la familia.","why":"Sujeto distinto (*das Badezimmer*): solo *damit*. *soll* desaparece: *damit … frei ist*.","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Una semana normal de Marcello (A), su mujer (B) y sus hijos (C). Une cada pareja de frases en una sola. Usa *um … zu* cuando la persona es la misma; si no, *damit*. Donde funcionan las dos, se acepta cualquiera.","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"Voy una vez por semana al supermercado para que mi mujer no tenga que hacer las compras pesadas.","why":"Persona distinta (*meine Frau*): solo *damit*. Aquí *muss* se queda, porque lleva el significado (*nicht machen muss* = no tiene que).","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"Cocino en casa al mediodía para que los niños tengan algo caliente para comer cuando vuelven de la escuela.","why":"Persona distinta (*die Kinder*): *damit*; *sollen* desaparece.","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"Mejoro mi alemán en un curso de idiomas para desenvolverme bien en el día a día.","why":"Misma persona: funcionan las dos. *zurechtkommen* es separable: *zurecht**zu**kommen*. *will* desaparece.","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"Después de la escuela estudiamos mucho por la tarde para sacar buenas notas y obtener un buen título.","why":"Misma persona (*wir*): funcionan las dos. Con dos verbos, cada uno lleva su propio *zu*.","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"Ayudamos en casa para que mamá no lo haga todo sola.","why":"Persona distinta (*Mama*): solo *damit*; *soll* desaparece.","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Quiero estar en la tienda para poder esperar allí.","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"¿Qué es correcto? Escribe *um* o *damit*. Fíjate en el final de la frase: *zu* + infinitivo necesita *um*; un verbo conjugado al final necesita *damit*.","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime estudia y trabaja mucho para establecerse pronto por su cuenta.","why":"*zu machen* al final → *um*.","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"Said aprende inglés además de alemán para tener mejores oportunidades en el mercado laboral.","why":"*zu haben* al final → *um*.","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Irina trabaja ahora a tiempo completo para que su marido pueda hacer un curso de formación caro.","why":"Sujeto nuevo *ihr Mann* y *kann* al final → *damit*.","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"El señor Pfister paga mucho dinero para que a sus padres los cuide una auxiliar de enfermería privada.","why":"Sujeto nuevo *seine Eltern*, pasiva *gepflegt werden* al final → *damit*.","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"¿Por qué hace esto Marcello?","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"Relaciona cada cosa que hace Marcello (1–6) con la persona que se beneficia (*Er, Seine Frau, Sein Team*) y con el objetivo (a–f). Escribe la persona y luego la letra.","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"Es el primero en llegar a la oficina. → Él, e (puede planificar su jornada sin que lo molesten).","why":"Una oficina vacía significa que no hay interrupciones.","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"Deja el coche en casa. → Su mujer, d (puede hacer las compras en coche durante el día).","why":"Si él no coge el coche, su mujer puede usarlo.","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"A veces hace horas extra. → Su equipo, b (puede terminar a tiempo el proyecto común).","why":"Las horas extra ayudan al proyecto común.","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"A veces también trabaja el sábado. → Él, c (quiere salir antes los días laborables).","why":"Trabajar el sábado le da días laborables más cortos.","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"Acuesta a los niños. → Su mujer, a (debe tener algo de tranquilidad por la noche).","why":"Ella tiene una noche tranquila.","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"Escribe frases con tus respuestas de a. Misma persona (*Er*): *um … zu* o *damit*. Otra persona: solo *damit*. Quita *will* y *soll*.","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"Es el primero en llegar a la oficina para planificar su jornada sin que lo molesten.","why":"Misma persona: funcionan las dos.","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"Deja el coche en casa para que su mujer pueda hacer las compras en coche durante el día.","why":"Otra persona: solo *damit*.","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"A veces hace horas extra para que su equipo pueda terminar a tiempo el proyecto común.","why":"Otro sujeto: solo *damit*.","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"A veces también trabaja el sábado para salir antes los días laborables.","why":"Misma persona: funcionan las dos; *will* desaparece.","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"Acuesta a los niños para que su mujer tenga algo de tranquilidad por la noche.","why":"Otra persona: *damit*; *soll* desaparece.","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"Trabajo y carrera: ¿qué cuenta para tener éxito en el trabajo? Encuentra cinco palabras más en la sopa de letras y completa las frases. *Kompetenzen* es el ejemplo. Escribe los adjetivos en minúscula.","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"Por ejemplo, es importante que una persona sepa trabajar bien en equipo y también llegue a acuerdos. Entonces sabe trabajar en equipo.","why":"*teamfähig* = capaz de trabajar en equipo.","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"Si unos compañeros discuten pero al final encuentran juntos una buena solución a su problema, entonces saben gestionar conflictos.","why":"*konfliktfähig* = capaz de gestionar conflictos.","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"Quien es abierto, sabe conversar bien con la gente pero también sabe escuchar, tiene buenas competencias comunicativas.","why":"Adjetivo delante de un sustantivo en plural después de *gute*: *kommunikative Kompetenzen*.","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"En cualquier caso, un empleado tiene que mostrar motivación y compromiso para tener éxito en el trabajo.","why":"*die Motivation* y *das Engagement* (compromiso); en cualquier orden.","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Hacer algo en lugar de solo soñar","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"Descontento en el trabajo","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"Compara las dos frases cortas con la larga. ¿Qué palabra para \"no / ningún\" desaparece en la versión con *statt … zu* u *ohne … zu*? Escríbela.","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"El jefe siempre está de mal humor. No tiene ningún motivo para ello. / El jefe siempre está de mal humor sin tener ningún motivo para ello. → keinen","why":"*ohne* ya significa \"no\": *keinen Grund* se convierte en *einen Grund* después de *ohne*.","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"¿Qué final es correcto? Las dos opciones aparecen encima de cada frase. Escribe el final correcto.","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"Cambio de trabajo en lugar de seguir enfadándome por el trabajo.","why":"Sin *nicht* después de *statt*: *statt* ya dice \"esto no\".","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"Busco un trabajo nuevo sin informar al jefe.","why":"Sin *nicht* después de *ohne*: *ohne den Chef nicht zu informieren* significaría lo contrario.","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"Trabajar desde casa. Convierte la segunda parte (lo que no haces) en *statt … zu* + infinitivo. Quita *nicht / keine*.","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"Tienes un horario flexible en lugar de trabajar de 9 a 17 h.","why":"*nicht* desaparece; *zu arbeiten* va al final.","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"No tienes gastos de desplazamiento en lugar de gastar mucho dinero en gasolina.","why":"*ausgeben* es separable: *aus**zu**geben*.","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"Ordenas el piso en lugar de trabajar.","why":"No hay nada más que pertenezca a *arbeiten*, así que el grupo es solo *statt zu arbeiten*.","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"Tienes que resolver muchos problemas solo en lugar de hablarlos con los compañeros.","why":"*sie* = los problemas; se queda dentro del grupo.","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Mi trabajadora compañera Olga. Une las dos frases. Algo que hace *en lugar de* otra cosa → *statt … zu*. Algo que no ocurre *al mismo tiempo* → *ohne … zu*. Quita *nicht / kein*.","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"Llega a la oficina ya a las 7 en lugar de empezar a las 9.","why":"Las 7 sustituyen a las 9 → *statt*. *anfangen*: *an**zu**fangen*.","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"Siempre va al trabajo en bici en lugar de coger el coche.","why":"La bici sustituye al coche → *statt*. (*das Velo* = palabra suiza para bicicleta.)","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"A la hora del almuerzo sale a correr en lugar de comer algo.","why":"Correr sustituye al almuerzo → *statt*.","source":"komma","check":"La clave oficial tiene *statt etwas zu essen*. *ohne etwas zu essen* (sale a correr y no come nada) también es alemán correcto y aquí significa casi lo mismo."},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"Trabaja muchas horas seguidas sin hacer ninguna pausa.","why":"Mientras trabaja no hay pausa → *ohne*. *keine Pause* se convierte en *eine Pause*.","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"Debería cuidarse más a sí misma en lugar de trabajar tanto.","why":"Cuidarse debería sustituir a trabajar tanto → *statt*.","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Hacer algo en lugar de solo soñar","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"Costumbres de la mañana. Escribe *ohne* o *statt*. *statt* = en lugar de (una cosa sustituye a otra); *ohne* = sin (algo no ocurre al mismo tiempo).","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"Por la mañana siempre me ducho con agua fría en lugar de darme un baño caliente.","why":"Una ducha fría sustituye a un baño caliente.","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"Nunca tomo café sin leer el periódico.","why":"*nie … ohne* = cada vez que tomo café, leo el periódico.","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"Nunca salgo de casa sin llevarme el paraguas.","why":"*nie … ohne* = siempre me lo llevo.","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"Por la mañana, después de despertarme, siempre me quedo media hora más en la cama en lugar de levantarme enseguida.","why":"Quedarse en la cama sustituye a levantarse.","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"¿Qué te gustaría hacer en tu vida? Combina un deseo de la parte izquierda del recuadro con algo de la parte derecha, usando *ohne … zu* o *statt … zu*. Las palabras tachadas se usan en el ejemplo. La respuesta modelo es una posibilidad.","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"Me gustaría ganar más dinero en lugar de tener que ahorrar cada franco. Me gustaría reparar las cosas rotas en lugar de tirarlas a la basura. Me gustaría hablar por teléfono con mi familia en mi país sin sentir nostalgia. Me gustaría ir en bici en lugar de ir siempre a pie. Me gustaría hablar bien alemán sin hacer muchos cursos de idiomas. Me gustaría vivir con mi familia en lugar de vivir solo.","why":"Deseo con *würde gern* / *wäre gern*, luego *statt … zu* (sustitución) u *ohne … zu* (no ocurre). Con un verbo modal: *sparen **zu müssen***.","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"Descontenta en un trabajo nuevo: consejos para una amiga","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Completa los consejos con las expresiones del recuadro. Cada una se usa una vez; *Wie wäre es, wenn* se usa en el ejemplo.","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"Si quieres conocer mejor a tus compañeros, quizás deberías pasar más a menudo durante el día un momento por la cocina del café. Allí puedes charlar tranquilamente con todos sin molestarlos en el trabajo.","why":"Después de la oración con *wenn*, el verbo va primero: *…, solltest du vielleicht …*; *gehen* va al final.","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"¿Qué te parece la idea de llevar un día un pastel para los compañeros de tu departamento y celebrar tu primer mes en la nueva empresa? A todo el mundo le alegra un pastel.","why":"*Wie findest du die Idee, … zu …?* es una pregunta con *zu* + infinitivo.","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"Yo en tu lugar iría a cualquier sitio donde se pueda encontrar a compañeros. Podrías, por ejemplo, participar en el programa deportivo de la empresa. Así también conocerás a gente de otros departamentos.","why":"*An deiner Stelle würde ich …* (yo en tu lugar); *Du könntest zum Beispiel …* + infinitivo al final.","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"Solo puedo aconsejarte que seas abierta y pienses en positivo. Ya verás, en unas semanas ya te sentirás mejor.","why":"*Ich kann dir nur raten, … zu …*: el consejo va como *zu* + infinitivo.","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"Escribe dos consejos más para la amiga. La respuesta modelo es una posibilidad.","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"Solo puedo aconsejarte que hables con tu jefa. ¿Qué te parece la idea de quedar con tus compañeros después del trabajo?","why":"Las dos expresiones llevan *zu* + infinitivo al final; con un verbo reflexivo, el pronombre se queda dentro: *dich … zu verabreden*.","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"Conversaciones de venta","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"Quería …","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"¿Quién dice qué? Escribe *K* para la clienta (*Kundin*) o *V* para la dependienta (*Verkäuferin*).","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"¿Puedo recomendarle …? → dependienta","why":"Recomendar es tarea de la dependienta.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"Tengo que pensármelo. → clienta","why":"La clienta todavía no se ha decidido.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"¿Necesita ayuda? → dependienta","why":"Ofrecer ayuda.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"¿Qué desea? → dependienta","why":"La dependienta pregunta qué quieres.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"Perdone, ¿es posible …? → clienta","why":"La clienta pide algo.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"¿Desea algo más? → dependienta","why":"Se pregunta hacia el final de una venta.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"Estoy buscando … → clienta","why":"La clienta dice lo que necesita.","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"Quería … → clienta","why":"Forma cortés de pedir algo (Konjunktiv II).","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"¿En qué puedo ayudarle? → dependienta","why":"Ofrecer ayuda.","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"¿Busca algo en concreto? → dependienta","why":"La dependienta pregunta qué quieres.","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"¿Puedo ofrecerle …? → dependienta","why":"Ofrecer algo.","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"Todavía no me puedo decidir. → clienta","why":"La clienta no se ha decidido.","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"¿Podría preguntarle algo? ¿Se puede …? → clienta","why":"Pregunta cortés (Konjunktiv II *dürfte*).","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"¿Quiere algo más? → dependienta","why":"Se pregunta hacia el final de una venta.","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"¿Qué frase de la derecha (a–h) significa lo mismo que cada frase de la izquierda? Escribe la letra.","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"¿Puedo recomendarle …? → e ¿Puedo ofrecerle …?","why":"Las dos proponen algo a la clienta.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"Tengo que pensármelo. → f Todavía no me puedo decidir.","why":"Las dos dicen: todavía no me he decidido.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"¿Necesita ayuda? → b ¿En qué puedo ayudarle?","why":"Las dos ofrecen ayuda.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"¿Qué desea? → d ¿Busca algo en concreto?","why":"Las dos preguntan qué quiere la clienta.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"Perdone, ¿es posible …? → g ¿Podría preguntarle algo? ¿Se puede …?","why":"Las dos son preguntas corteses de la clienta.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"¿Desea algo más? → h ¿Quiere algo más?","why":"Las dos preguntan si la clienta quiere algo más.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"Estoy buscando … → a Quería …","why":"Las dos dicen lo que quiere la clienta.","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"Reclamaciones","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"Completa las frases de cartas de reclamación. El libro da algunas letras de cada palabra (aparecen encima de la frase); escribe la palabra completa. (El ejercicio 22 es de comprensión auditiva y se omite.)","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"Les pido por última vez que me respondan antes del 31 de marzo.","why":"*jemanden auffordern, … zu …* = exigir a alguien que …; separable: *ich fordere … auf*.","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"Por desgracia, el reloj que compré ayer no funciona. Envíenme un repuesto, por favor. Tengo derecho a un reloj nuevo.","why":"*der Ersatz* = repuesto, sustituto; *Anspruch haben auf* + acusativo = tener derecho a.","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"Cuando abrí el paquete, por desgracia comprobé que el/la … está dañado/a.","why":"*beschädigt* = dañado.","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"Ya les he escrito dos veces sin recibir respuesta. Es realmente muy molesto.","why":"*ärgerlich* = molesto, fastidioso.","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"El jersey es bonito, pero por desgracia a mi marido no le queda bien. Por eso me gustaría cambiarlo por una talla más grande.","why":"*umtauschen* = cambiar (en una tienda).","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"Por desgracia, todavía no he recibido respuesta.","why":"*die Antwort* = respuesta.","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"Confírmenme por escrito, por favor, que han recibido mi reclamación.","why":"*bestätigen* = confirmar.","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"Estoy muy molesto y muy decepcionado con su servicio.","why":"*verärgert* = enfadado, molesto; *enttäuscht von* = decepcionado con.","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"Una reclamación por escrito","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"Las frases de la izquierda son como se escribe en una carta de reclamación; el recuadro muestra cómo se diría en el habla cotidiana. Escribe la letra (a–g) con el mismo significado.","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"El 16 de febrero me entregaron … → g","why":"Las dos dicen qué recibiste y cuándo.","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"Ya les he escrito dos veces un correo electrónico pidiéndoles que me envíen un repuesto. → b","why":"*bereits* = *schon*; *Ersatz* = uno nuevo. (*das E-Mail* es uso suizo.)","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"Por desgracia, todavía no he recibido respuesta. → f","why":"Todavía sin respuesta → decepcionado.","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"Tengo que decir que su servicio me ha decepcionado mucho. → e","why":"Esperabas un servicio mejor.","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"Les pido por última vez que me envíen un repuesto antes del … → d","why":"*zum letzten Mal* = *ein letztes Mal*.","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"Si no tengo noticias suyas antes del …, renuncio al pedido. → a","why":"*auf etwas verzichten* = prescindir de algo / renunciar a algo.","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"Elige una situación y escribe una reclamación como en a. Las frases 1–7 te ayudan. Las respuestas modelo son una posibilidad cada una.","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"Estimados señores y señoras: / El 12 de marzo me entregaron unos auriculares. Por desgracia, no funcionan. Ya les he escrito una vez, pero no he recibido respuesta. Les pido por última vez que me envíen un repuesto antes del 12 de abril. Si de nuevo no recibo respuesta suya, renunciaré al pedido. / Saludos cordiales / Luca Carelli","why":"Los puntos clave en orden: qué recibiste y cuándo, qué falla, qué has hecho, qué debe hacer la empresa (*auffordern, … zu …*) y qué harás si no.","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"Estimados señores y señoras: / El 3 de mayo me entregaron una funda para portátil. Por desgracia, la correa se rompió después de solo una semana. Es muy molesto. Hoy les devuelvo la funda y les pido que me la cambien o que me envíen un repuesto. Adjunto encontrarán una copia de la factura. Confírmenme por escrito, por favor, que han recibido mi reclamación. / Saludos cordiales / Maria Keller","why":"Nuestro propio modelo (la clave no tiene ninguno para la situación 2). *bitten, … zu …*: *umzutauschen* (separable).","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"Test de la lección 6","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa el texto. El libro da algunas letras de cada palabra (aparecen encima de la frase); escribe la palabra completa.","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"… pero en algún momento estuve descontento y tomé una decisión: me establezco por mi cuenta como comerciante y fundo una empresa.","why":"*sich entschliessen* (Perfekt: *hat sich entschlossen*) = decidirse. *der Kaufmann* = comerciante.","source":"g6865","check":"Las letras dadas apuntan a *Kaufmann*; una mujer escribiría *Kauffrau*, que tiene otras letras. Se aceptan las dos. La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"Me ayudan unos amigos que son buenos comerciantes.","why":"*die Geschäftsleute* = comerciantes, gente de negocios (plural).","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"No creo que sea un riesgo económico. Al contrario, creo que vale la pena.","why":"*ein finanzielles Risiko* (neutro); *es lohnt sich* = vale la pena.","source":"platzhalter","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"Une las dos frases. Usa *um … zu* cuando la persona es la misma; si no, usa *damit*.","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás hace un curso de formación para mejorar sus competencias comunicativas.","why":"Misma persona (Tomás) → *um … zu*; *möchte* desaparece.","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"La señora Seil solo trabaja media jornada para que los niños no estén solos cuando vuelven de la escuela.","why":"Otra persona (los niños) → *damit*; *sollen* desaparece.","source":"damit","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Rodolfo se ocupa de los niños esta semana para que su mujer pueda visitar a su madre enferma.","why":"Otra persona (su mujer) → *damit*; *kann* va al final.","source":"damit","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"Escribe *ohne* o *statt* en el primer hueco y *zu* en el segundo.","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"Uno sabe llegar a acuerdos si en una disputa se pone de acuerdo con alguien en lugar de discutir sin resultado.","why":"Ponerse de acuerdo sustituye a discutir → *statt*.","source":"komma","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"Un buen jefe es alguien que dirige a sus empleados sin darse demasiada importancia.","why":"Dirige y al mismo tiempo no se da demasiada importancia → *ohne*. El primer *zu* significa \"demasiado\".","source":"komma","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"Quien sabe trabajar en equipo trabaja con gusto con los compañeros en lugar de hacerlo siempre todo solo.","why":"El trabajo en equipo sustituye a trabajar solo → *statt*.","source":"komma","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"Flexible es alguien que puede acostumbrarse a situaciones nuevas rápido y sin problemas, sin estar estresado.","why":"El estrés no aparece → *ohne*.","source":"komma","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"Antes de la entrevista de trabajo: consejos para un amigo. Escribe la expresión que encaja con el resto de la frase. Las dos opciones aparecen encima de cada frase.","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"¿Qué tal si piensas unas cuantas preguntas que puedas hacer mañana?","why":"*du … überlegst* con el verbo al final necesita *wenn*: *Wie wäre es, wenn …?*","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"Podrías, por ejemplo, preguntar lo grande que es el equipo o cuáles serán tus tareas.","why":"Después de un verbo modal va un infinitivo simple (*fragen*): *Du könntest … fragen*.","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"Solo puedo aconsejarte que seas tú mismo. Eso es lo más importante de todo.","why":"*zu sein* necesita una expresión que lleve *zu* + infinitivo: *Ich kann dir nur raten, …*","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"¿Qué te parece salir a cenar esta noche? Así piensas en otra cosa.","why":"*essen zu gehen* (zu + infinitivo) encaja con *Was hältst du davon, … zu …?*","source":"g6865","check":"La clave de soluciones del Arbeitsbuch no cubre el test de la lección; esta respuesta es nuestra, comprobada con grammis."}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"Enfoque en el trabajo: peticiones de clientes","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"Trabajad en grupos de tres: cada persona asume un papel y representáis tres llamadas telefónicas. Practica escribiéndolas o diciéndolas; los diálogos modelo son una posibilidad. (Los ejercicios 1 y 2 son de comprensión auditiva y se omiten.)","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"Clienta: Buenos días, soy la señora Meier. Les pedí tres cajas de agua mineral y cuatro cajas de zumo de manzana. Acaba de llegar la entrega, pero son siete cajas de agua mineral. ¡Pedí zumo de manzana y no solo agua! / Empleado: Oh, lo siento. Debe de haber habido un error. Llamo enseguida a mi compañero. Deme su número de móvil, por favor, y la llamo enseguida.","why":"Reclamación: di qué pediste y qué ha llegado (*bestellt … und nicht …*). El empleado se disculpa y promete volver a llamar. (*der Harass* = palabra suiza para caja de bebidas; *der Süssmost* = zumo de manzana suizo.)","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"Empleado: Hola, Marco, ha llamado la señora Meier. Le entregaste siete cajas de agua mineral en lugar de tres cajas de agua y cuatro de zumo de manzana. / Conductor: Vaya, parece que me he confundido. ¿Y ahora qué hacemos? Podría volver a ir esta tarde. / Empleado: Bien, haremos lo siguiente: le llevas cuatro cajas de zumo de manzana y recoges cuatro cajas de agua. Yo la llamo y le pregunto si le parece bien.","why":"Entre compañeros se usa *du*. Aquí *statt* + sustantivo (*statt drei Harasse Wasser*): la misma idea que *statt … zu*, pero con una cosa.","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"Empleado: Señora Meier, lo siento muchísimo. Mi compañero se ha equivocado. Podríamos llevarle el zumo de manzana hoy mismo antes de las 17 h. Por supuesto, le hacemos un descuento del 20 por ciento. / Clienta: Sí, me parece bien. La fiesta no empieza hasta las 18 h. ¡Muchas gracias!","why":"Ofrece una solución con *Wir könnten Ihnen …* (Konjunktiv II = cortés). La clienta acepta: *damit bin ich einverstanden* (aquí *damit* = con eso, no *para que*).","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (clave oficial de soluciones, Lektion 6)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um … zu no tiene sujeto propio; lo toma de la oración principal)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"Diccionario de conectores de grammis: damit (subjuntor con el verbo al final; también adverbio con el sentido de \"con eso\")","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (las oraciones de infinitivo con um, ohne, (an)statt se separan con una coma)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis: Platzhalter (es en la posición 1; el es formal con los verbos del tiempo atmosférico se queda: Heute schneit es)","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis: Korrelat (es que anuncia una oración: Ich kann es nicht erwarten, euch zu sehen)","url":"https://grammis.ids-mannheim.de/vggf/2283"}]},{"id":"06-lektion-6-zusatzblaetter","no":6,"title":"Lektion 6 Homework – extra exercises from printed sheets","title_en":"En lugar de (*anstatt … zu / anstatt dass*), sin (*ohne … zu / ohne dass*), finalidad (*um … zu / damit*)","added":"2026-11-20","book":"Printed grammar sheets 48, 49 and 52 (extra homework for Schritte plus Neu 5, Lektion 6)","pages":[{"page":"Blatt 48 · S. 100","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"Me gusta invitar a amigos en lugar de comer solo. (Oración principal + oración de infinitivo / oración modal: *anstatt … zu, anstatt dass*)","exercises":[{"no":"A","instruction":"Welches Foto passt? Kreuzen Sie an.","instruction_en":"¿Qué foto encaja con la frase? Foto A: amigos comiendo juntos en una mesa grande. Foto B: un hombre comiendo solo. Escribe A o B. Abajo se muestran los recuadros de reglas B y C de la hoja.","reading":[{"label":"B  Lesen Sie.","text":"Infinitiv mit anstatt … zu: Ich lade gerne Freunde ein, | anstatt immer allein zu essen.\nNebensatz mit anstatt dass: Ich lade gerne Freunde ein, | anstatt dass ich immer allein esse.\nDie Subjekte in Haupt- und Nebensatz sind gleich: anstatt … zu oder anstatt dass\nIch lade gerne Freunde ein, | anstatt immer allein zu essen. / anstatt dass ich immer allein esse.\nDie Subjekte in Hauptsatz und Nebensatz sind nicht gleich: immer anstatt dass\nEr lädt gerne Freunde ein, | anstatt dass wir immer allein essen."},{"label":"C  Lesen Sie.","text":"• *anstatt … zu* und *anstatt dass* signalisieren, dass eine Alternative möglich ist.\n• Im Infinitivsatz mit *anstatt … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz.\n• Man kann *anstatt* oder *statt* benutzen, es gibt keinen Unterschied: Wir lachen anstatt zu weinen. = Wir lachen statt zu weinen."}],"items":[{"label":"1","text":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto ___","gaps":[["A"]],"solution":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto **A**","en":"Me gusta invitar a amigos en lugar de comer siempre solo. → Foto A","why":"La foto A muestra a los amigos en la mesa, la alternativa que él eligió; la foto B muestra lo que *no* hace.","source":"anstattdass"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"¿Qué frases son correctas? Escribe *richtig* o *falsch*. Consejo: *anstatt* ya significa \"esto no\", así que no le sigue ningún *nicht* ni *kein*.","example":[{"label":"1","text":"Ich verabrede mich mit Freunden, anstatt allein fernzusehen. → **richtig**"}],"items":[{"label":"2","text":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → ___","gaps":[["falsch"]],"solution":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → **falsch**","en":"Quedo con amigos en lugar de no ver la tele solo. → falso","why":"*anstatt* ya niega: *anstatt nicht …* dice lo contrario de lo que se quiere decir.","source":"anstattdass"},{"label":"3","text":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → ___","gaps":[["falsch"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → **falsch**","en":"Publico mi libro en Amazon en lugar de no buscar ninguna editorial. → falso","why":"No va *kein* después de *anstatt*: la acción sustituida es *einen Verlag suchen*.","source":"anstattdass"},{"label":"4","text":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → ___","gaps":[["richtig"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → **richtig**","en":"Publico mi libro en Amazon en lugar de buscar una editorial. → correcto","why":"Acción en positivo después de *anstatt*, *zu* + infinitivo al final.","source":"g6865"}]}]},{"page":"Blatt 48 · S. 101","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"Me gusta invitar a amigos en lugar de comer solo.","exercises":[{"no":"2","instruction":"Vereine. Verbinden Sie die Sätze mit *anstatt … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Asociaciones. Une las dos frases con *anstatt … zu*. La segunda frase dice lo que *no* ocurre: quita su *nicht* y su sujeto, y pon *zu* + infinitivo al final.","example":[{"label":"1","lead":"Ich werde Mitglied in einem Fussballverein. Ich mache nicht allein Sport.","text":"Ich werde Mitglied in einem Fussballverein, **anstatt allein Sport zu machen**."}],"items":[{"label":"2","lead":"Sie können den Mitgliedsbeitrag auch monatlich überweisen. Sie zahlen nicht sofort fürs ganze Jahr.","text":"","accept":["Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.","Sie können den Mitgliedsbeitrag auch monatlich überweisen, statt sofort fürs ganze Jahr zu zahlen."],"solution":"**Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.**","en":"También puede transferir la cuota de socio cada mes en lugar de pagar el año entero de una vez.","why":"*nicht* desaparece; *zu zahlen* va al final.","source":"g6865"},{"label":"3","lead":"Wir nehmen Tom in unseren Verein auf. Wir sagen ihm nicht wieder ab.","text":"","accept":["Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.","Wir nehmen Tom in unseren Verein auf, statt ihm wieder abzusagen."],"solution":"**Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.**","en":"Admitimos a Tom en nuestra asociación en lugar de volver a rechazarlo.","why":"Verbo separable: *zu* va entre el prefijo y el verbo: *abzusagen* (ab + zu + sagen).","source":"g6865"},{"label":"4","lead":"Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen. Sie werden nicht sofort Mitglied.","text":"","accept":["Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.","Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, statt sofort Mitglied zu werden."],"solution":"**Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.**","en":"También puede venir primero sin más a nuestros eventos en lugar de hacerse socio enseguida.","why":"Mismo sujeto *Sie*: *anstatt … Mitglied zu werden*.","source":"g6865"}]},{"no":"3","instruction":"Unterstreichen Sie die Subjekte. Welche sind gleich? Kreuzen Sie an.","instruction_en":"Busca el sujeto de cada frase (quién hace la acción) y luego di si es la misma persona o cosa. Escribe los dos sujetos y luego *gleich* (igual) o *nicht gleich* (no igual). Atención: el sujeto no siempre está en la posición 1.","example":[{"label":"1","text":"Sie möchte Bücher schreiben. Sie arbeitet nicht weiter im Büro. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Die Autoren"],["nicht gleich"]],"solution":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → **Der Verlag** / **Die Autoren** → **nicht gleich**","en":"La editorial ahora solo quiere desarrollar apps. Los autores no escriben libros. → no es el mismo","why":"Dos sujetos distintos: *der Verlag* y *die Autoren*.","source":"anstattdass"},{"label":"3","text":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → ___ / ___ → ___","gaps":[["Sie"],["sie"],["gleich"]],"solution":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → **Sie** / **sie** → **gleich**","en":"Ella publica la novela en autoedición. No envía el manuscrito a una editorial. → es el mismo","why":"*Das Manuskript* es el objeto (es lo que se envía); el sujeto *sie* va después del verbo.","source":"g6865"},{"label":"4","text":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Er"],["gleich"]],"solution":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → **Der Verlag** / **Er** → **gleich**","en":"La editorial ahora solo publica en línea. No imprime libros. → es el mismo","why":"*Er* se refiere a *der Verlag*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze aus 4 mit *anstatt … zu* und / oder *anstatt dass*.","instruction_en":"Une las frases del ejercicio 3 (la hoja dice \"aus 4\" por error). Mismo sujeto: funcionan las dos formas. Sujetos distintos: solo *anstatt dass*. Quita *nicht* / convierte *kein* en *ein* o en nada.","example":[{"label":"1","text":"anstatt … zu: Sie möchte Bücher schreiben, **anstatt weiter im Büro zu arbeiten**.\nanstatt dass: Sie möchte Bücher schreiben, **anstatt dass sie weiter im Büro arbeitet**."}],"items":[{"label":"2 · anstatt dass","lead":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher.","text":"","accept":["Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.","Der Verlag möchte nur noch Apps entwickeln, statt dass die Autoren Bücher schreiben."],"solution":"**Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.**","en":"La editorial ahora solo quiere desarrollar apps, en lugar de que los autores escriban libros.","why":"Sujetos distintos → solo *anstatt dass*; *keine Bücher* → *Bücher*; verbo al final.","source":"anstattdass"},{"label":"3 · anstatt … zu","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.","Sie veröffentlicht den Roman im Selbstverlag, statt das Manuskript an einen Verlag zu schicken."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.**","en":"Publica la novela en autoedición en lugar de enviar el manuscrito a una editorial.","why":"Mismo sujeto: sin *sie* en la oración de infinitivo, sin coma antes de *zu*.","source":"g6865"},{"label":"3 · anstatt dass","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.","Sie veröffentlicht den Roman im Selbstverlag, statt dass sie das Manuskript an einen Verlag schickt."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.**","en":"Publica la novela en autoedición en lugar de enviar el manuscrito a una editorial.","why":"*anstatt dass* necesita su propio sujeto *sie*; el verbo *schickt* va al final.","source":"anstattdass"},{"label":"4 · anstatt … zu","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.","Der Verlag veröffentlicht nur noch online, statt Bücher zu drucken."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.**","en":"La editorial ahora solo publica en línea en lugar de imprimir libros.","why":"*keine Bücher* → *Bücher*; *zu drucken* al final.","source":"g6865"},{"label":"4 · anstatt dass","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.","Der Verlag veröffentlicht nur noch online, statt dass er Bücher druckt."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.**","en":"La editorial ahora solo publica en línea en lugar de imprimir libros.","why":"Sujeto *er* + verbo *druckt* al final.","source":"anstattdass"}]},{"no":"5","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *anstatt … zu*.","instruction_en":"¿Qué te gustaría hacer? Combina un deseo de la primera parte del recuadro (*Ich würde gerne …*) con algo de la segunda parte (*anstatt … zu*). Las expresiones tachadas se usan en el ejemplo. La respuesta modelo es una posibilidad.","box":["Sport in einem Verein machen","an einem Tag Homeoffice machen","öfter an die frische Luft gehen","schöne Dinge kaufen","etwas mit meiner Familie unternehmen","immer nur sparen","jeden Tag ins Büro fahren","immer allein joggen","am Wochenende arbeiten","immer im klimatisierten Büro sitzen"],"box_used":[0,7],"example":[{"label":"Beispiel","text":"Ich würde gerne Sport in einem Verein machen, **anstatt immer allein zu joggen**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne an einem Tag Homeoffice machen, anstatt jeden Tag ins Büro zu fahren. Ich würde gerne öfter an die frische Luft gehen, anstatt immer im klimatisierten Büro zu sitzen. Ich würde gerne schöne Dinge kaufen, anstatt immer nur zu sparen. Ich würde gerne etwas mit meiner Familie unternehmen, anstatt am Wochenende zu arbeiten.","en":"Me gustaría trabajar desde casa un día a la semana en lugar de ir a la oficina todos los días. Me gustaría salir más a menudo al aire libre en lugar de estar siempre sentado en la oficina con aire acondicionado. Me gustaría comprar cosas bonitas en lugar de solo ahorrar siempre. Me gustaría hacer algo con mi familia en lugar de trabajar el fin de semana.","why":"Deseo con *würde gerne* + infinitivo, luego *anstatt … zu* + infinitivo al final; *nur* se queda delante de *zu sparen*.","source":"g6865"}]}]},{"page":"Blatt 49 · Seite 1","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Trabajo aquí sin estar estresado. (Oración principal + oración de infinitivo / oración modal: *ohne … zu, ohne dass*)","exercises":[{"no":"A","instruction":"Lesen Sie und unterstreichen Sie *ohne … zu*.","instruction_en":"Lee el bocadillo y escribe la parte con *ohne … zu*. Abajo se muestran los recuadros de reglas B y C de la hoja.","reading":[{"label":"Sprechblase","text":"Homeoffice! Ja, cool! Ich arbeite hier, ohne Stress zu haben."},{"label":"B  Lesen Sie.","text":"Infinitiv mit ohne zu: Ich arbeite hier, | ohne Stress zu haben.\nNebensatz mit ohne dass: Ich arbeite hier, | ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind gleich: ohne zu oder ohne dass\nIch arbeite hier, | ohne Stress zu haben. / ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind verschieden: immer ohne dass\nIch arbeite hier, | ohne dass mein Chef Stress macht."},{"label":"C  Lesen Sie.","text":"• *ohne … zu* und *ohne dass* drücken aus, dass etwas nicht ist oder nicht passiert.\n• Im Infinitivsatz mit *ohne … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz."}],"items":[{"label":"1","text":"Homeoffice! Ja, cool! Ich arbeite hier, ___.","gaps":[["ohne Stress zu haben"]],"solution":"Homeoffice! Ja, cool! Ich arbeite hier, **ohne Stress zu haben**.","en":"¡Trabajar desde casa! ¡Sí, genial! Aquí trabajo sin tener estrés.","why":"*ohne* abre la oración, *zu* + infinitivo la cierra.","source":"g6865"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"¿Qué frases son correctas? Escribe *richtig* o *falsch*. Consejo: *ohne* ya significa \"no\", así que no le sigue ningún *nicht* ni *kein*.","example":[{"label":"1","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn zu stören. → **richtig**"}],"items":[{"label":"2","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → ___","gaps":[["falsch"]],"solution":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → **falsch**","en":"Aquí puedo tocar bien el piano sin no molestar a los vecinos. → falso","why":"*ohne … nicht* es una doble negación: significaría que *sí* los molestas.","source":"ohnedass"},{"label":"3","text":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → ___","gaps":[["richtig"]],"solution":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → **richtig**","en":"Gana un sueldo más alto sin trabajar una hora más por ello. → correcto","why":"*ohne* + expresión en positivo (*eine Stunde*) + *zu arbeiten*.","source":"g6865"},{"label":"4","text":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → ___","gaps":[["falsch"]],"solution":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → **falsch**","en":"Gana un sueldo más alto sin trabajar ninguna hora más por ello. → falso","why":"No va *kein* después de *ohne*: *keine Stunde* pasa a ser *eine Stunde*.","source":"ohnedass"}]}]},{"page":"Blatt 49 · Seite 2","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Trabajo aquí sin estar estresado.","exercises":[{"no":"2","instruction":"Der Alltag eines Bloggers. Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"La vida cotidiana de un bloguero. Une las dos frases con *ohne … zu*. Quita *nicht*; convierte *kein* en *ein* (o quítalo delante de un plural).","example":[{"label":"1","lead":"Ich arbeite bequem von zu Hause. Ich fahre nicht ins Büro.","text":"Ich arbeite bequem von zu Hause, **ohne ins Büro zu fahren**."}],"items":[{"label":"2","lead":"Ich arbeite selbstständig. Ich habe keinen Vertrag.","text":"","accept":["Ich arbeite selbstständig, ohne einen Vertrag zu haben."],"solution":"**Ich arbeite selbstständig, ohne einen Vertrag zu haben.**","en":"Trabajo por mi cuenta sin tener un contrato.","why":"*keinen Vertrag* → *einen Vertrag*: *ohne* ya dice \"no\".","source":"ohnedass"},{"label":"3","lead":"Ich mache Pausen und gehe auch mal zum Sport. Ich informiere meine Kollegen nicht.","text":"","accept":["Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren."],"solution":"**Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren.**","en":"Hago pausas y a veces voy a hacer deporte sin informar a mis compañeros.","why":"*nicht* desaparece; *zu informieren* al final.","source":"g6865"},{"label":"4","lead":"Ich wähle die Themen für meinen Blog. Ich frage den Chef nicht.","text":"","accept":["Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen."],"solution":"**Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen.**","en":"Elijo los temas de mi blog sin preguntar al jefe.","why":"*nicht* desaparece; el objeto *den Chef* va antes de *zu fragen*.","source":"g6865"},{"label":"5","lead":"Ich habe viel Zeit für mein Kind. Ich mache mir keine Sorgen um meine Karriere.","text":"","accept":["Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen."],"solution":"**Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen.**","en":"Tengo mucho tiempo para mi hijo sin preocuparme por mi carrera.","why":"*keine Sorgen* → *Sorgen* (plural: sin artículo); el reflexivo *mir* se queda.","source":"ohnedass"}]},{"no":"3","instruction":"Mein Leben. *ohne dass* oder *ohne*? Unterstreichen Sie.","instruction_en":"Mi vida. Escribe *ohne dass* u *ohne*. Fíjate en el final: *zu* + infinitivo → *ohne*; un sujeto nuevo y un verbo conjugado al final → *ohne dass*.","example":[{"label":"1","text":"Ich möchte abends Musik hören, **ohne dass** sich meine Nachbarn beschweren."}],"items":[{"label":"2","text":"Ich trinke nie Kaffee, ___ dabei Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** dabei Zeitung zu lesen.","en":"Nunca tomo café sin leer el periódico a la vez.","why":"*zu lesen* al final, sin sujeto nuevo → *ohne*.","source":"g6865"},{"label":"3","text":"Ich gehe nie ins Theater, ___ mich vorher über das Stück zu informieren.","gaps":[["ohne"]],"solution":"Ich gehe nie ins Theater, **ohne** mich vorher über das Stück zu informieren.","en":"Nunca voy al teatro sin informarme antes sobre la obra.","why":"*zu informieren* al final → *ohne*; *mich* es el reflexivo, no un sujeto.","source":"g6865"},{"label":"4","text":"Meine Kinder gehen nie aus, ___ ich etwas davon weiss.","gaps":[["ohne dass"]],"solution":"Meine Kinder gehen nie aus, **ohne dass** ich etwas davon weiss.","en":"Mis hijos nunca salen sin que yo lo sepa.","why":"Sujeto nuevo *ich*, *weiss* al final → *ohne dass*.","source":"ohnedass"}]},{"no":"4","instruction":"Computer. Unterstreichen Sie die Subjekte. Sind sie (nicht) gleich? Kreuzen Sie an.","instruction_en":"Ordenadores. Busca el sujeto de cada frase y escribe los dos sujetos, luego *gleich* (igual) o *nicht gleich* (no igual). *Sie* con mayúscula = \"usted\" de cortesía.","example":[{"label":"1","text":"Sie verlässt einfach das Büro. Sie sichert die Daten im Computer nicht. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → ___ / ___ → ___","gaps":[["Die Firma"],["Wir"],["nicht gleich"]],"solution":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → **Die Firma** / **Wir** → **nicht gleich**","en":"La empresa guarda nuestros datos. No tenemos ni idea. → no es el mismo","why":"Dos sujetos distintos: *die Firma* y *wir*.","source":"ohnedass"},{"label":"3","text":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → ___ / ___ → ___","gaps":[["Wir"],["Wir"],["gleich"]],"solution":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → **Wir** / **Wir** → **gleich**","en":"Deberíamos procesar los datos electrónicamente. No esperamos mucho. → es el mismo","why":"En las dos frases: *wir*.","source":"g6865"},{"label":"4","text":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → ___ / ___ → ___","gaps":[["Sie"],["Der Techniker"],["nicht gleich"]],"solution":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → **Sie** / **Der Techniker** → **nicht gleich**","en":"Usted puede instalar el software. El técnico no le ayuda. → no es el mismo","why":"*Ihnen* es el objeto en dativo; el sujeto de la segunda frase es *der Techniker*.","source":"ohnedass"},{"label":"5","text":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → ___ / ___ → ___","gaps":[["Ich"],["Ich"],["gleich"]],"solution":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → **Ich** / **Ich** → **gleich**","en":"Conecto el ordenador. No pregunto al departamento de informática. → es el mismo","why":"En las dos frases: *ich*.","source":"g6865"}]},{"no":"5","instruction":"Verbinden Sie die Sätze aus 4 mit *ohne dass* und, wo möglich, mit *ohne zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Une las frases del ejercicio 4 con *ohne dass* y, donde los sujetos son los mismos, también con *ohne … zu*. Quita *nicht*; convierte *keine* en *eine*.","example":[{"label":"1","text":"Sie verlässt einfach das Büro, **ohne die Daten im Computer zu sichern**.\nSie verlässt einfach das Büro, **ohne dass sie die Daten im Computer sichert**."}],"items":[{"label":"2 · ohne dass","lead":"Die Firma speichert unsere Daten. Wir haben keine Ahnung.","text":"","accept":["Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.","Die Firma speichert unsere Daten, ohne dass wir eine Ahnung davon haben."],"solution":"**Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.**","en":"La empresa guarda nuestros datos sin que tengamos ni idea.","why":"Sujetos distintos → solo *ohne dass*; *keine Ahnung* → *eine Ahnung*.","source":"ohnedass"},{"label":"3 · ohne … zu","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten.**","en":"Deberíamos procesar los datos electrónicamente sin esperar mucho.","why":"Mismo sujeto: *nicht* desaparece, *zu warten* al final.","source":"g6865"},{"label":"3 · ohne dass","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten.**","en":"Deberíamos procesar los datos electrónicamente sin esperar mucho.","why":"Se repite el sujeto *wir*, *warten* al final.","source":"ohnedass"},{"label":"4 · ohne dass","lead":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht.","text":"","accept":["Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.","Sie können die Software installieren, ohne dass Ihnen der Techniker hilft."],"solution":"**Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.**","en":"Usted puede instalar el software sin que el técnico le ayude.","why":"Sujetos distintos → solo *ohne dass*; *hilft* al final.","source":"ohnedass"},{"label":"5 · ohne … zu","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen."],"solution":"**Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen.**","en":"Conecto el ordenador sin preguntar al departamento de informática.","why":"Mismo sujeto: *ohne die IT-Abteilung zu fragen*.","source":"g6865"},{"label":"5 · ohne dass","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage."],"solution":"**Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage.**","en":"Conecto el ordenador sin preguntar al departamento de informática.","why":"Se repite el sujeto *ich*, *frage* al final.","source":"ohnedass"}]},{"no":"6","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"¿Qué te gustaría hacer? Combina un deseo de la primera parte del recuadro con algo de la segunda parte, usando *ohne … zu*. Las expresiones tachadas se usan en el ejemplo. La respuesta modelo es una posibilidad.","box":["viel Geld verdienen","eine eigene Firma gründen","fliessend Deutsch sprechen","mehrmals im Jahr verreisen","immer sparen","noch mehr arbeiten","Sprachkurse besuchen","die Risiken tragen"],"box_used":[0,5],"example":[{"label":"Beispiel","text":"Ich würde gerne viel Geld verdienen, **ohne noch mehr zu arbeiten**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne eine eigene Firma gründen, ohne die Risiken zu tragen. Ich würde gerne fliessend Deutsch sprechen, ohne Sprachkurse zu besuchen. Ich würde gerne mehrmals im Jahr verreisen, ohne immer zu sparen.","en":"Me gustaría fundar mi propia empresa sin asumir los riesgos. Me gustaría hablar alemán con fluidez sin ir a cursos de idiomas. Me gustaría viajar varias veces al año sin estar siempre ahorrando.","why":"Deseo con *würde gerne* + infinitivo, luego *ohne … zu* + infinitivo al final.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 108","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Conduzco despacio para ahorrar gasolina. (Oración principal + oración final: *um … zu, damit*)","exercises":[{"no":"A","instruction":"Lesen Sie und ordnen Sie zu.","instruction_en":"Lee y relaciona cada frase con una foto. Foto A: un hombre girando el termostato de un radiador. Foto B: unas manos en un volante. Escribe A o B. Abajo se muestran los recuadros de reglas B y C de la hoja.","reading":[{"label":"Alles, um die Umwelt zu schützen","text":"1 Ich fahre langsam, um Benzin zu sparen.\n2 Um Energie zu sparen, schalten wir die Heizung nachts aus."},{"label":"B  Lesen Sie.","text":"Infinitiv mit um zu: Ich fahre langsam, | um Benzin zu sparen.\nNebensatz mit damit: Ich fahre langsam, | damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind gleich: um zu oder damit\nIch fahre langsam, | um Benzin zu sparen. / damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind nicht gleich: immer damit\nMeine Eltern sparen, | damit ich studieren kann."},{"label":"C  Lesen Sie.","text":"• *um … zu* und *damit* drücken einen Zweck oder eine Absicht aus.\n• Der Satz mit *um … zu* ist ein Infinitivsatz. Am Ende steht der Infinitiv."}],"items":[{"label":"1","text":"Foto ___: Ich fahre langsam, um Benzin zu sparen.","gaps":[["B"]],"solution":"Foto **B**: Ich fahre langsam, um Benzin zu sparen.","en":"Foto B: Conduzco despacio para ahorrar gasolina.","why":"Conducir → el volante.","source":"adverbial"},{"label":"2","text":"Foto ___: Um Energie zu sparen, schalten wir die Heizung nachts aus.","gaps":[["A"]],"solution":"Foto **A**: Um Energie zu sparen, schalten wir die Heizung nachts aus.","en":"Foto A: Para ahorrar energía, apagamos la calefacción por la noche.","why":"Calefacción → el radiador. Cuando *um … zu* va primero, la oración principal empieza por el verbo: *schalten wir*.","source":"g6865"}]},{"no":"1","instruction":"Wozu das? Verbinden Sie die Sätze mit *um … zu* und schreiben Sie in Ihr Heft.","instruction_en":"¿Para qué? Une cada frase con la finalidad entre paréntesis, usando *um … zu*: *um* después de la coma, *zu* + infinitivo al final.","example":[{"label":"1","lead":"Wir fahren in die Berge. (→ wandern und ein Picknick machen)","text":"Wir fahren in die Berge, **um zu wandern und ein Picknick zu machen**."}],"items":[{"label":"2","lead":"Wir fahren an den See. (→ dort spazieren gehen)","text":"","accept":["Wir fahren an den See, um dort spazieren zu gehen."],"solution":"**Wir fahren an den See, um dort spazieren zu gehen.**","en":"Vamos al lago para dar un paseo allí.","why":"Dos verbos: *zu* va delante del último: *spazieren zu gehen*.","source":"g6865"},{"label":"3","lead":"Wir haben lange gespart. (→ die Wohnung kaufen)","text":"","accept":["Wir haben lange gespart, um die Wohnung zu kaufen."],"solution":"**Wir haben lange gespart, um die Wohnung zu kaufen.**","en":"Hemos ahorrado durante mucho tiempo para comprar el piso.","why":"*um die Wohnung zu kaufen*: el objeto va entre *um* y *zu*.","source":"g6865"},{"label":"4","lead":"Ich muss in die Klinik. (→ meinen kranken Onkel besuchen)","text":"","accept":["Ich muss in die Klinik, um meinen kranken Onkel zu besuchen."],"solution":"**Ich muss in die Klinik, um meinen kranken Onkel zu besuchen.**","en":"Tengo que ir a la clínica para visitar a mi tío enfermo.","why":"*um … zu besuchen*.","source":"g6865"},{"label":"5","lead":"Ihr müsst mehr trainieren. (→ am Marathon teilnehmen können)","text":"","accept":["Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können."],"solution":"**Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können.**","en":"Tenéis que entrenar más para poder participar en el maratón.","why":"Con un verbo modal, *zu* va delante del modal: *teilnehmen zu können*.","source":"g6865"},{"label":"6","lead":"Du musst Sport machen. (→ gesund bleiben)","text":"","accept":["Du musst Sport machen, um gesund zu bleiben."],"solution":"**Du musst Sport machen, um gesund zu bleiben.**","en":"Tienes que hacer deporte para mantenerte sano.","why":"*um gesund zu bleiben*.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 109","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Conduzco despacio para ahorrar gasolina.","exercises":[{"no":"2","instruction":"Ordnen Sie zu und verbinden Sie Sätze mit *damit*. Beginnen Sie die Sätze auch mit *damit*. Schreiben Sie in Ihr Heft.","instruction_en":"Relaciona cada pregunta con un objetivo (a–c) y luego responde dos veces: una con *damit* después de la oración principal y otra empezando por *Damit*. En la oración con *damit*, el verbo va al final; después de una oración con *Damit* al principio, la oración principal empieza por su verbo.","phrases":["a  Wir prüfen endlich die Rechnung.","b  Meine Frau wartet nicht so lange.","c  Ich repariere ihr Fahrrad.","d  Du verstehst mich gut. (Beispiel)"],"example":[{"label":"1","lead":"Wozu übst du die Aussprache? → d","text":"Ich übe die Aussprache, **damit du mich gut verstehst**.\n**Damit du mich gut verstehst**, übe ich die Aussprache."}],"items":[{"label":"2","text":"Wozu holt Paul den Taschenrechner? → ___","gaps":[["a"]],"solution":"Wozu holt Paul den Taschenrechner? → **a**","en":"Paul trae la calculadora para que por fin revisemos la cuenta.","why":"Busca el objetivo que encaja con la pregunta.","source":"damit"},{"label":"2 · damit am Ende","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.","Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen können."],"solution":"**Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.**","en":"Paul trae la calculadora para que por fin revisemos la cuenta.","why":"Sujeto nuevo *wir* → *damit*; *prüfen* al final.","source":"damit"},{"label":"2 · Damit am Anfang","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.","Damit wir endlich die Rechnung prüfen können, holt Paul den Taschenrechner."],"solution":"**Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.**","en":"Para que por fin revisemos la cuenta, Paul trae la calculadora.","why":"Oración con *Damit* al principio, luego el verbo: *holt Paul*.","source":"damit"},{"label":"3","text":"Wozu fahren Sie so schnell? → ___","gaps":[["b"]],"solution":"Wozu fahren Sie so schnell? → **b**","en":"Conduzco tan rápido para que mi mujer no tenga que esperar tanto.","why":"Busca el objetivo que encaja con la pregunta.","source":"damit"},{"label":"3 · damit am Ende","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Ich fahre so schnell, damit meine Frau nicht so lange wartet.","Ich fahre so schnell, damit meine Frau nicht so lange warten muss."],"solution":"**Ich fahre so schnell, damit meine Frau nicht so lange wartet.**","en":"Conduzco tan rápido para que mi mujer no tenga que esperar tanto.","why":"La pregunta usa *Sie*, la respuesta *ich*. Aquí *nicht* se queda: *damit* no niega.","source":"damit"},{"label":"3 · Damit am Anfang","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Damit meine Frau nicht so lange wartet, fahre ich so schnell.","Damit meine Frau nicht so lange warten muss, fahre ich so schnell."],"solution":"**Damit meine Frau nicht so lange wartet, fahre ich so schnell.**","en":"Para que mi mujer no tenga que esperar tanto, conduzco tan rápido.","why":"Oración con *Damit* al principio, luego *fahre ich*.","source":"damit"},{"label":"4","text":"Wozu hat Emilia eine Zange mitgenommen? → ___","gaps":[["c"]],"solution":"Wozu hat Emilia eine Zange mitgenommen? → **c**","en":"Emilia ha traído unos alicates para que yo le repare la bici.","why":"Busca el objetivo que encaja con la pregunta.","source":"damit"},{"label":"4 · damit am Ende","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.","Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad reparieren kann."],"solution":"**Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.**","en":"Emilia ha traído unos alicates para que yo le repare la bici.","why":"*ihr Fahrrad* = la bici de Emilia; sujeto nuevo *ich* → *damit*.","source":"damit"},{"label":"4 · Damit am Anfang","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.","Damit ich ihr Fahrrad reparieren kann, hat Emilia eine Zange mitgenommen."],"solution":"**Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.**","en":"Para que yo le repare la bici, Emilia ha traído unos alicates.","why":"Oración con *Damit* al principio, luego *hat Emilia … mitgenommen*.","source":"damit"}]},{"no":"3","instruction":"Welche Sätze kann man mit *um … zu* verbinden? Kreuzen Sie an.","instruction_en":"¿Qué parejas se pueden unir con *um … zu*? Solo cuando las dos frases tienen el mismo sujeto. Escribe *ja* o *nein*.","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation. Ich möchte die Teamleitung bekommen. → **ja**"}],"items":[{"label":"2","text":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → ___","gaps":[["nein"]],"solution":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → **nein**","en":"Betty hace un curso de verano en París. Sus notas de francés mejoran. → no","why":"Los sujetos *Betty* e *ihre Noten* son distintos.","source":"g6865"},{"label":"3","text":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → ___","gaps":[["ja"]],"solution":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → **ja**","en":"Necesitamos su consentimiento. Queremos enviarle publicidad. → sí","why":"En las dos: *wir*.","source":"g6865"},{"label":"4","text":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → ___","gaps":[["ja"]],"solution":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → **ja**","en":"David todavía tiene suficiente energía también por la noche. Quiere hacer deporte. → sí","why":"*Er* = David.","source":"g6865"},{"label":"5","text":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → ___","gaps":[["nein"]],"solution":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → **nein**","en":"Esta noche ya lo preparo todo. Podéis salir mañana muy temprano. → no","why":"Los sujetos *ich* e *ihr* son distintos.","source":"g6865"},{"label":"6","text":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → ___","gaps":[["nein"]],"solution":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → **nein**","en":"Compramos cada vez más productos ecológicos. Nuestros hijos pueden comer sano. → no","why":"Los sujetos *wir* y *unsere Kinder* son distintos.","source":"g6865"},{"label":"7","text":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → ___","gaps":[["ja"]],"solution":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → **ja**","en":"Emma y Pia quedan en el centro. Quieren ir de compras juntas. → sí","why":"*Sie* = Emma y Pia.","source":"g6865"},{"label":"8","text":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → ___","gaps":[["ja"]],"solution":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → **ja**","en":"Necesitas un buen método de trabajo. Quieres resolver las tareas rápidamente. → sí","why":"En las dos: *du*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze in 3 mit *damit* und, wo möglich, mit *um … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Une las parejas del ejercicio 3 con *damit* y, donde el sujeto es el mismo, también con *um … zu*. *möchte(n)* desaparece: la palabra de finalidad ya expresa \"querer\".","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation, **um die Teamleitung zu bekommen**.\nIch mache eine Zusatzqualifikation, **damit ich die Teamleitung bekomme**."}],"items":[{"label":"2 · damit","lead":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser.","text":"","accept":["Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.","Betty macht einen Sommerkurs in Paris, damit ihre Französischnoten besser werden."],"solution":"**Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.**","en":"Betty hace un curso de verano en París para que sus notas de francés mejoren.","why":"Sujetos distintos → solo *damit*; *werden* al final.","source":"damit"},{"label":"3 · um … zu","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken.**","en":"Necesitamos su consentimiento para enviarle publicidad.","why":"Verbo separable: *zuzuschicken* (zu + zu + schicken); *möchten* desaparece.","source":"g6865"},{"label":"3 · damit","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken können.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.**","en":"Necesitamos su consentimiento para que se nos permita enviarle publicidad.","why":"*damit wir … zuschicken dürfen*: el consentimiento da permiso, así que *dürfen* es lo que mejor encaja.","source":"damit","check":"La hoja no tiene solucionario: aquí funcionan *dürfen*, *können* o ningún modal; pregunta a tu profesor cuál quiere."},{"label":"4 · um … zu","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, um Sport zu machen."],"solution":"**David hat auch abends noch genügend Energie, um Sport zu machen.**","en":"David todavía tiene suficiente energía también por la noche para hacer deporte.","why":"Mismo sujeto: *um Sport zu machen*.","source":"g6865"},{"label":"4 · damit","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, damit er Sport machen kann.","David hat auch abends noch genügend Energie, damit er Sport macht."],"solution":"**David hat auch abends noch genügend Energie, damit er Sport machen kann.**","en":"David todavía tiene suficiente energía también por la noche para poder hacer deporte.","why":"Se repite el sujeto *er*, verbo al final.","source":"damit"},{"label":"5 · damit","lead":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren.","text":"","accept":["Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt."],"solution":"**Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt.**","en":"Esta noche ya lo preparo todo para que podáis salir mañana muy temprano.","why":"Sujetos distintos → solo *damit*; *könnt* al final del todo.","source":"damit"},{"label":"6 · damit","lead":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen.","text":"","accept":["Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können."],"solution":"**Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können.**","en":"Compramos cada vez más productos ecológicos para que nuestros hijos puedan comer sano.","why":"Sujetos distintos → solo *damit*.","source":"damit"},{"label":"7 · um … zu","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen.**","en":"Emma y Pia quedan en el centro para ir de compras juntas.","why":"Verbo separable: *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"7 · damit","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.","Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.**","en":"Emma y Pia quedan en el centro para poder ir de compras juntas.","why":"Se repite el sujeto *sie*, verbo al final.","source":"damit"},{"label":"8 · um … zu","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen."],"solution":"**Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen.**","en":"Necesitas un buen método de trabajo para resolver las tareas rápidamente.","why":"Mismo sujeto: *um … zu lösen*.","source":"g6865"},{"label":"8 · damit","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.","Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell löst."],"solution":"**Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.**","en":"Necesitas un buen método de trabajo para poder resolver las tareas rápidamente.","why":"Se repite el sujeto *du*, verbo al final.","source":"damit"}]},{"no":"5","instruction":"Lesen Sie Frau Deckers Blog und verbinden Sie die Sätze mit *um … zu* oder *damit*.","instruction_en":"Lee el blog de la señora Decker y une cada pareja: mismo sujeto → *um … zu* (lo mejor); sujeto distinto → *damit*. Quita *möchte*.","reading":[{"label":"www.mein-tag.de","text":"1 Ich stehe morgens früh auf. Ich möchte noch vor dem Frühstück joggen.\n2 Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.\n3 Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.\n4 Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.\n5 Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein."}],"example":[{"label":"1","text":"Ich stehe morgens früh auf, **um noch vor dem Frühstück zu joggen**."}],"items":[{"label":"2","lead":"Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.","text":"","accept":["Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.","Ich fahre oft mit dem Auto ins Büro, damit ich pünktlich bin."],"solution":"**Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.**","en":"A menudo voy a la oficina en coche para ser puntual.","why":"Mismo sujeto *ich* → *um pünktlich zu sein*.","source":"g6865"},{"label":"3","lead":"Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.","text":"","accept":["Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind."],"solution":"**Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind.**","en":"Por la mañana trabajo rápido y concentrado para que mis clientes estén satisfechos.","why":"Sujeto nuevo *meine Kunden* → *damit*; *sind* al final.","source":"damit"},{"label":"4","lead":"Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.","text":"","accept":["Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.","Ich fahre in der Mittagspause in den Supermarkt, damit ich schnell etwas fürs Abendessen einkaufe."],"solution":"**Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.**","en":"En la pausa del mediodía voy al supermercado para comprar rápidamente algo para la cena.","why":"Mismo sujeto; verbo separable: *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"5","lead":"Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein.","text":"","accept":["Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind."],"solution":"**Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind.**","en":"Salgo de la empresa a las tres para que mis hijos no estén solos demasiado tiempo.","why":"Sujeto nuevo *meine Kinder* → *damit*; *nicht* se queda (solo *ohne* y *anstatt* lo absorben).","source":"damit"}]},{"no":"6","instruction":"Wozu machen Sie was? Schreiben Sie 3 Sätze über Ihren Tag in Ihr Heft und nennen Sie den Zweck.","instruction_en":"¿Qué haces y para qué? Escribe 3 frases sobre tu día y da la finalidad con *um … zu* o *damit*. La respuesta modelo es una posibilidad.","example":[{"label":"Beispiel","text":"Ich gehe schon um drei aus dem Büro, **um früh bei den Kindern zu sein**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich stehe um halb sieben auf, um den Zug nach Zürich zu erreichen. Ich nehme mein Mittagessen von zu Hause mit, um Geld zu sparen. Am Abend lerne ich eine halbe Stunde Deutsch, damit meine Chancen im Job besser werden.","en":"Me levanto a las seis y media para coger el tren a Zúrich. Me llevo la comida de casa para ahorrar dinero. Por la noche estudio alemán media hora para que mejoren mis oportunidades en el trabajo.","why":"Mismo sujeto → *um … zu*; un sujeto nuevo (*meine Chancen*) → *damit*.","source":"adverbial"}]}]}],"sources":[{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um / ohne / anstatt … zu no tienen sujeto propio; lo toman de la oración principal)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"Diccionario de conectores de grammis: damit (subjuntor con el verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"adverbial","title":"grammis: Adverbial (las oraciones con um … zu y damit son complementos circunstanciales de finalidad)","url":"https://grammis.ids-mannheim.de/vggf/2280"},{"id":"ohnedass","title":"Diccionario de conectores de grammis: ohne dass (subjuntor, verbo al final; induce negación: la oración dice lo que no ocurre)","url":"https://grammis.ids-mannheim.de/konnektoren/406910"},{"id":"anstattdass","title":"Diccionario de conectores de grammis: anstatt dass (subjuntor, verbo al final; sustitutivo e inductor de negación; también statt dass)","url":"https://grammis.ids-mannheim.de/konnektoren/406953"}]}];
